-- Shared projections already contain the approved, version-bound private location.
create or replace function public.demo_overlay_field_locations() returns trigger
language plpgsql security definer set search_path='' as $$
declare r record; g jsonb; items jsonb := coalesce(new.payload->'locations','[]');
begin
 if exists(select from public.demo_catalogs where owner_id=new.owner_id and workspace_id=new.workspace_id and desktop_shared) then return new;end if;
 for r in select distinct on(grave_id) * from public.demo_location_requests
 where owner_id=new.owner_id and workspace_id=new.workspace_id and status='approved' order by grave_id,seq desc loop
  g:=public.demo_location_grave(new.owner_id,new.workspace_id,r.grave_id);
  if g is null or g->>'address' is distinct from r.original_address then continue; end if;
  select coalesce(jsonb_agg(item),'[]') into items from jsonb_array_elements(items) item where item->>'id'<>r.grave_id::text;
  items:=items || jsonb_build_array(jsonb_build_object('id',r.grave_id,'address',r.original_address,'region',coalesce(g->>'region','지역 미확인'),'location',jsonb_build_object('lat',r.latitude,'lng',r.longitude,'source','field')));
 end loop;
 -- Stable ordering avoids changing revisions for identical coordinates.
 select coalesce(jsonb_agg(item order by (item->>'id')::bigint),'[]') into items from jsonb_array_elements(items) item;
 new.payload:=jsonb_set(new.payload,'{locations}',items);
 return new;
end $$;

-- Supplemental schema protection. The original demo_schema registry is not rewritten.
create table if not exists demo_desktop.schema_releases(version text primary key,source_sha256 text not null,target jsonb not null,applied_at timestamptz not null default clock_timestamp());
create table if not exists demo_desktop.schema_pending(id boolean primary key default true check(id),xid bigint not null,version text not null,source_sha256 text not null,target jsonb not null);
do $$declare t text;begin
 foreach t in array array['schema_releases','schema_pending'] loop
  if not (select relrowsecurity from pg_class where oid=to_regclass('demo_desktop.'||t)) then execute format('alter table demo_desktop.%I enable row level security',t);end if;
  execute format('revoke all on demo_desktop.%I from public,anon,authenticated,service_role',t);
  if exists(select from pg_roles where rolname='demo_desktop_writer') then execute format('revoke all on demo_desktop.%I from demo_desktop_writer',t);end if;
 end loop;
end $$;
create or replace function demo_desktop.schema_fingerprint(p_key text) returns jsonb
language plpgsql stable set search_path='' as $$declare kind text:=split_part(p_key,':',1);name text:=substr(p_key,strpos(p_key,':')+1);oid_value oid;value jsonb;begin
 if kind='function' then return demo_schema.fingerprint(name);
 elsif kind='table' then
  oid_value:=to_regclass(name);if oid_value is null then return null;end if;
  select jsonb_build_object('rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'owner',r.rolname,
   'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
   'constraints',(select coalesce(jsonb_agg(jsonb_build_array(n.conname,pg_get_constraintdef(n.oid,true),n.convalidated) order by n.conname collate "C"),'[]') from pg_constraint n where n.conrelid=c.oid and n.contype<>'n'),
   'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when v=0 then 'PUBLIC' else (v::regrole)::text end order by v) from unnest(p.polroles) v),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname collate "C"),'[]') from pg_policy p where p.polrelid=c.oid),
   'acl',(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else (a.grantee::regrole)::text end,a.privilege_type,a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else (a.grantee::regrole)::text end collate "C",a.privilege_type collate "C"),'[]') from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a)) into value from pg_class c join pg_roles r on r.oid=c.relowner where c.oid=oid_value;
  return value;
 elsif kind='schema' then
  select jsonb_build_object('owner',(n.nspowner::regrole)::text,'acl',(select coalesce(jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else (a.grantee::regrole)::text end,a.privilege_type,a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else (a.grantee::regrole)::text end collate "C",a.privilege_type collate "C"),'[]') from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a)) into value from pg_namespace n where n.nspname=name;return value;
 elsif kind='index' then
  select jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) into value from pg_index i where i.indexrelid=to_regclass(name);return value;
 elsif kind='trigger' then
  select jsonb_build_object('definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) into value from pg_trigger t where t.tgrelid=to_regclass(split_part(name,':',1)) and t.tgname=split_part(name,':',2);return value;
 elsif kind='role' then
  select jsonb_build_object('superuser',r.rolsuper,'login',r.rolcanlogin,'createDb',r.rolcreatedb,'createRole',r.rolcreaterole,'inherit',r.rolinherit,'replicate',r.rolreplication,'bypassRls',r.rolbypassrls,
   'members',(select coalesce(jsonb_agg(jsonb_build_array(m.member_name,case when m.member_name='postgres' then true else m.admin_option end,m.inherit_option,m.set_option) order by m.member_name collate "C"),'[]') from (select (g.member::regrole)::text member_name,bool_or(g.admin_option) admin_option,bool_or(g.inherit_option) inherit_option,bool_or(g.set_option) set_option from pg_auth_members g where g.roleid=r.oid group by g.member) m)) into value from pg_roles r where r.rolname=name;return value;
 elsif kind='event-trigger' then
  select jsonb_build_object('event',evtevent,'enabled',evtenabled,'tags',evttags,'function',evtfoid::regprocedure::text) into value from pg_event_trigger where evtname=name;return value;
 end if;
 raise exception 'Unknown protected desktop object';
end $$;
create or replace function demo_desktop.schema_targets() returns jsonb language plpgsql stable set search_path='' as $$declare result jsonb;begin
 select jsonb_object_agg(key,demo_desktop.schema_fingerprint(key)) into result from (
  select 'function:'||n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')' key from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='demo_desktop' or (n.nspname='public' and (p.proname like 'demo_desktop_%' or p.proname='demo_sales_assignment'))
  union all select 'table:'||n.nspname||'.'||c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='demo_desktop' and c.relkind='r'
  union all select 'index:'||n.nspname||'.'||c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='demo_desktop' and c.relkind='i'
  union all select 'trigger:'||n.nspname||'.'||c.relname||':'||t.tgname from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname='demo_desktop' or (n.nspname='public' and t.tgname in ('privacy_index_event','privacy_index_receipt','prune_work_allocations')))
  union all select 'function:public.'||p.proname||'('||oidvectortypes(p.proargtypes)||')' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('demo_append_change','demo_bank_context','demo_bank_commit','demo_reserve_report','demo_publish_report','demo_report_dispatch_events')
  union all select 'table:public.'||name from unnest(array['demo_events','demo_sync_changes','demo_sync_state','demo_bank_receipts','demo_work_reports']) name
  union all select unnest(array['schema:demo_desktop','function:public.demo_access(uuid)','function:public.demo_can_manage(uuid,uuid)','function:public.demo_is_staff()','function:public.demo_desktop_access(uuid,uuid,text)','function:public.demo_overlay_field_locations()','table:public.demo_location_requests','trigger:public.demo_location_requests:desktop_location_gate','table:public.demo_earth_assets','trigger:public.demo_earth_assets:desktop_earth_gate','trigger:demo_desktop.earth_links:desktop_earth_retire','trigger:demo_desktop.graves:desktop_earth_grave_removed','table:public.demo_catalogs','table:public.demo_map_snapshots','trigger:public.demo_catalogs:desktop_catalog_gate','trigger:public.demo_map_snapshots:desktop_map_gate','trigger:demo_desktop.schema_pending:desktop_release_must_finish','trigger:public.demo_events:aaa_desktop_event_lock','trigger:public.demo_events:desktop_billed_amounts','index:public.desktop_event_claim_reference','role:demo_desktop_writer','event-trigger:demo_desktop_guard_ddl','event-trigger:demo_desktop_guard_drop'])
 ) targets;
 return result;
end $$;
create or replace function demo_desktop.assert_schema() returns void language plpgsql set search_path='' as $$declare target jsonb;item record;begin
 perform pg_advisory_xact_lock(hashtextextended('demo-schema-application',0));
 perform pg_advisory_xact_lock(hashtextextended('demo-desktop-application',0));
 perform demo_schema.assert_current();
 -- Only the administrator's staged transaction can expose intermediate DDL; COMMIT validates every final fingerprint.
 if exists(select from demo_desktop.schema_pending where xid=txid_current()) then return;end if;
 select r.target into target from demo_desktop.schema_releases r order by r.version desc limit 1;
 if target is null then return;end if;
 for item in select * from jsonb_each(target) loop
  if demo_desktop.schema_fingerprint(item.key) is distinct from item.value then raise exception 'Protected desktop object changed: %',item.key;end if;
 end loop;
 if exists(select from demo_desktop.schema_pending) then raise exception 'Unfinished desktop schema release';end if;
end $$;
create or replace function demo_desktop.begin_upgrade(p_version text,p_sha text,p_expected jsonb,p_target jsonb) returns boolean
language plpgsql set search_path='' as $$declare current_release demo_desktop.schema_releases;begin
 perform demo_desktop.assert_schema();
 if p_version is null or p_version!~'^[0-9]{8}-[a-z0-9-]+$' or p_sha is null or p_sha!~'^[a-f0-9]{64}$' or jsonb_typeof(p_target) is distinct from 'object' or not p_target ? 'function:public.demo_desktop_command(uuid, uuid, uuid, jsonb)' then raise exception 'Invalid desktop release';end if;
 select * into current_release from demo_desktop.schema_releases order by version desc limit 1;
 if exists(select from demo_desktop.schema_releases where version=p_version and source_sha256<>p_sha) then raise exception 'Desktop release hash conflict';end if;
 if current_release.version=p_version then
  if current_release.target is distinct from p_target then raise exception 'Desktop target conflict';end if;return false;
 end if;
 if current_release.version is not null and (p_version<current_release.version or current_release.target is distinct from p_expected) then raise exception 'Desktop release baseline mismatch';end if;
 if current_release.version is null and p_expected is distinct from '{}'::jsonb then raise exception 'Desktop release baseline mismatch';end if;
 insert into demo_desktop.schema_pending(xid,version,source_sha256,target) values(txid_current(),p_version,p_sha,p_target);
 return true;
end $$;
create or replace function demo_desktop.finish_upgrade(p_version text,p_sha text) returns void language plpgsql set search_path='' as $$declare p demo_desktop.schema_pending;item record;begin
 select * into p from demo_desktop.schema_pending where xid=txid_current() and version=p_version and source_sha256=p_sha;
 if not found then raise exception 'Desktop release was not started';end if;
 for item in select * from jsonb_each(p.target) loop
  if demo_desktop.schema_fingerprint(item.key) is distinct from item.value then raise exception 'Desktop release final mismatch: %',item.key;end if;
 end loop;
 insert into demo_desktop.schema_releases(version,source_sha256,target) values(p_version,p_sha,p.target);
 delete from demo_desktop.schema_pending;perform demo_desktop.assert_schema();
end $$;
create or replace function demo_desktop.check_schema_ddl() returns event_trigger language plpgsql security definer set search_path='' as $$begin perform demo_desktop.assert_schema();end $$;
create or replace function demo_desktop.check_schema_commit() returns trigger language plpgsql set search_path='' as $$begin
 if exists(select from demo_desktop.schema_pending where xid=txid_current()) then raise exception 'Unfinished desktop schema release';end if;return null;
end $$;
create or replace function demo_desktop.deployment_status() returns jsonb language plpgsql set search_path='' as $$declare r demo_desktop.schema_releases;core jsonb;begin
 perform demo_desktop.assert_schema();core:=demo_schema.status();select * into r from demo_desktop.schema_releases order by version desc limit 1;
 return jsonb_build_object('version',r.version,'sourceSha256',r.source_sha256,'coreValid',core->'valid','coreVersion',core->'version','coreSourceSha256',core->'sourceSha256','unfinished',(select count(*) from demo_desktop.schema_pending),'valid',r.version is not null and (core->>'valid')::boolean and not exists(select from demo_desktop.schema_pending));
end $$;
do $$begin
 if not exists(select from pg_trigger where tgrelid='demo_desktop.schema_pending'::regclass and tgname='desktop_release_must_finish') then create constraint trigger desktop_release_must_finish after insert on demo_desktop.schema_pending deferrable initially deferred for each row execute function demo_desktop.check_schema_commit();end if;
 if not exists(select from pg_event_trigger where evtname='demo_desktop_guard_ddl') then create event trigger demo_desktop_guard_ddl on ddl_command_end execute function demo_desktop.check_schema_ddl();end if;
 if not exists(select from pg_event_trigger where evtname='demo_desktop_guard_drop') then create event trigger demo_desktop_guard_drop on sql_drop execute function demo_desktop.check_schema_ddl();end if;
end $$;
revoke all on all functions in schema demo_desktop from public,anon,authenticated,service_role;

create or replace function public.demo_desktop_status(p_workspace uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 perform demo_desktop.assert_actor_for(p_workspace,'read');return demo_desktop.deployment_status();
end $$;
revoke all on function public.demo_desktop_status(uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_status(uuid) to authenticated;

-- Privacy successor: financial originals stay restricted; expiry automation is deferred.
-- Follow-up only: frozen source files remain unchanged.

create or replace function demo_desktop.privacy_enabled(p_owner uuid,p_workspace uuid) returns boolean language plpgsql stable security definer set search_path='' as $$begin
 if to_regclass('demo_desktop.privacy_state') is null then return false;end if;
 return coalesce((select enabled from demo_desktop.privacy_state where owner_id=p_owner and workspace_id=p_workspace),false);
end $$;

create or replace function demo_desktop.transfer_keys(p_value jsonb,p_keys text[]) returns void language plpgsql immutable set search_path='' as $$begin
 if jsonb_typeof(p_value) is distinct from 'object' or p_value-p_keys<>'{}' then perform demo_desktop.fail('invalid-input');end if;
end $$;

create or replace function demo_desktop.transfer_scalars(p_value jsonb,p_nested text[] default '{}'::text[]) returns void language plpgsql immutable set search_path='' as $$declare r record;begin
 if jsonb_typeof(p_value) is distinct from 'object' then perform demo_desktop.fail('invalid-input');end if;
 for r in select * from jsonb_each(p_value) loop
  if r.key=any(p_nested) then continue;end if;
  if jsonb_typeof(r.value) not in ('null','string','number') then perform demo_desktop.fail('invalid-input');end if;
  if r.key='sourceFile' and (jsonb_typeof(r.value) is distinct from 'string' or r.value#>>'{}' !~* '^.+\.(kml|kmz)$' or r.value#>>'{}' ~ '[\\/:<>"|?*]') then perform demo_desktop.fail('invalid-input');end if;
 end loop;
end $$;
create or replace function demo_desktop.transfer_coordinates(p_value jsonb,p_depth integer default 0) returns void language plpgsql immutable set search_path='' as $$declare v jsonb;begin
 if p_depth>3 then perform demo_desktop.fail('invalid-input');end if;
 if jsonb_typeof(p_value)='number' then return;end if;
 if jsonb_typeof(p_value) is distinct from 'array' or jsonb_array_length(p_value) not between 1 and 2001 then perform demo_desktop.fail('invalid-input');end if;
 for v in select value from jsonb_array_elements(p_value) loop perform demo_desktop.transfer_coordinates(v,p_depth+1);end loop;
end $$;
create or replace function demo_desktop.transfer_geometry(p_value jsonb) returns void language plpgsql immutable set search_path='' as $$begin
 perform demo_desktop.transfer_keys(p_value,array['type','coordinates']);
 if p_value->>'type' not in ('Point','Polygon') or not p_value ?& array['type','coordinates'] then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.transfer_coordinates(p_value->'coordinates');
end $$;

create or replace function demo_desktop.transfer_payload(p_value jsonb) returns jsonb language plpgsql immutable set search_path='' as $$declare k text;v jsonb;n jsonb;item record;allowed jsonb:='{"customers":["id","name","phone","phone_raw","phone_ok","memo","special_notes","registration_status","deleted_at","created_at"],"graves":["id","customer_id","address","gubun","seq","contract_year","gisu","pyeong","note","is_managed","business_region","is_active","deleted_at","created_at"],"payments":["id","grave_id","year","amount","kind","paid_at","method","source","note"],"annualWork":["id","year","customer_id","grave_id","status","notes","deadline","version","deleted_at"],"workRows":["key","customerId","graveId","serviceYear","sequence","number","address","gisu","name","notes","deadline","region","rowNumber","status","deleted_at"],"locations":["id","address","lookupAddress","location"],"location":["lat","lng","source","requestId","requestSeq","accuracy","measuredAt","requesterName","pnu","matchedAddress","datasetDate","fetchedAt","expiresAt"],"earthLinks":["graveId","versionId","summary"],"earthVersions":["versionId","graveId","manifest","state","uploadedAt"]}'::jsonb;begin
 perform demo_desktop.transfer_keys(p_value,array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','idCounters','events']);
 foreach k in array array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','events'] loop
  if jsonb_typeof(p_value->k) is distinct from 'array' or jsonb_array_length(p_value->k)>100000 then perform demo_desktop.fail('invalid-input');end if;
  for v in select value from jsonb_array_elements(p_value->k) loop
   if k='events' then perform demo_desktop.transfer_keys(v,array['id','workspaceId','kind','at','payload']);continue;end if;
   perform demo_desktop.transfer_keys(v,array(select jsonb_array_elements_text(allowed->k)));
   for item in select * from jsonb_each(v) loop
    if item.key in ('location','summary','manifest') then continue;end if;
    if jsonb_typeof(item.value) not in ('string','number','null') then perform demo_desktop.fail('invalid-input');end if;
   end loop;
   if k='graves' then
    if v ? 'is_managed' and v->'is_managed' not in ('0'::jsonb,'1'::jsonb) then perform demo_desktop.fail('invalid-input');end if;
    if v->>'business_region' is not null and (jsonb_typeof(v->'business_region') is distinct from 'string' or length(v->>'business_region')>100 or v->>'business_region' ~ '[[:cntrl:]]') then perform demo_desktop.fail('invalid-input');end if;
   end if;
   if k='payments' and v->>'source' is not null and v->>'source' not in ('desktop','desktop_sales','sent_claim','legacy_import') then perform demo_desktop.fail('invalid-input');end if;
   if k='locations' and v->'location' is not null and v->'location'<>'null' then
    n:=v->'location';perform demo_desktop.transfer_keys(n,array(select jsonb_array_elements_text(allowed->'location')));
    if jsonb_typeof(n->'lat') is distinct from 'number' or jsonb_typeof(n->'lng') is distinct from 'number' or abs((n->>'lat')::numeric)>90 or abs((n->>'lng')::numeric)>180 then perform demo_desktop.fail('invalid-input');end if;
    if exists(select from jsonb_each(n) x where jsonb_typeof(x.value) not in ('string','number','null')) then perform demo_desktop.fail('invalid-input');end if;
   end if;
   if k='earthLinks' then
    n:=v->'summary';perform demo_desktop.transfer_keys(n,array['source','originalAddress','confirmedAt','name','sourceFile','geometry','point','areaM2','asset']);
    perform demo_desktop.transfer_scalars(n,array['geometry','point','asset']);
    if n ? 'point' then perform demo_desktop.transfer_keys(n->'point',array['lat','lng']);perform demo_desktop.transfer_scalars(n->'point');end if;
    if n ? 'asset' then perform demo_desktop.transfer_keys(n->'asset',array['versionId','sha256','size','sourceFile','state']);perform demo_desktop.transfer_scalars(n->'asset');end if;
    if n ? 'geometry' then perform demo_desktop.transfer_geometry(n->'geometry');end if;
   end if;
   if k='earthVersions' then
    n:=v->'manifest';perform demo_desktop.transfer_keys(n,array['format','schemaVersion','versionId','workspaceId','graveId','originalAddress','importedAt','sourceFile','sha256','size','selection']);
    perform demo_desktop.transfer_scalars(n,array['selection']);
    perform demo_desktop.transfer_keys(n->'selection',array['name','geometry','point','areaM2']);
    perform demo_desktop.transfer_scalars(n->'selection',array['geometry','point']);
    perform demo_desktop.transfer_geometry(n->'selection'->'geometry');
    perform demo_desktop.transfer_keys(n->'selection'->'point',array['lat','lng']);
    perform demo_desktop.transfer_scalars(n->'selection'->'point');
   end if;
  end loop;
 end loop;
 perform demo_desktop.transfer_keys(p_value->'idCounters',array['customers','graves','payments']);
 return p_value;
end $$;

create or replace function demo_desktop.import_legacy(p_workspace uuid,p_request uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor(p_workspace);a uuid:=auth.uid();source jsonb;row_value jsonb;previous demo_desktop.requests;fingerprint text;result jsonb;server_revision text;k text;maximum bigint;counter bigint;cid bigint;gid bigint;event_value public.demo_events;begin
 if a<>o then perform demo_desktop.fail('access-denied');end if;
 if p_request is null or jsonb_typeof(p_input) is distinct from 'object' or p_input-array['sourceJson','sourceSha256','serverRevision']<>'{}' or jsonb_typeof(p_input->'sourceJson') is distinct from 'string' or octet_length(p_input->>'sourceJson')>20000000 or coalesce(p_input->>'sourceSha256','')!~'^[a-f0-9]{64}$' or jsonb_typeof(p_input->'serverRevision') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
 if encode(sha256(convert_to(p_input->>'sourceJson','UTF8')),'hex')<>p_input->>'sourceSha256' then perform demo_desktop.fail('source-mismatch');end if;
 begin source:=(p_input->>'sourceJson')::jsonb;exception when others then perform demo_desktop.fail('invalid-input');end;
 if jsonb_typeof(source) is distinct from 'object' or source-array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','idCounters','events']<>'{}' or jsonb_typeof(source->'idCounters') is distinct from 'object' then perform demo_desktop.fail('invalid-input');end if;
 foreach k in array array['customers','graves','payments','annualWork','workRows','locations','earthLinks','earthVersions','events'] loop if jsonb_typeof(source->k) is distinct from 'array' then perform demo_desktop.fail('invalid-input');end if;end loop;
 select revision into server_revision from public.demo_catalogs where owner_id=o and workspace_id=p_workspace for no key update;
 perform demo_desktop.lock_actor(p_workspace,o);
 fingerprint:=encode(sha256(convert_to('import:'||p_input::text,'UTF8')),'hex');
 select * into previous from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=a and request_id=p_request;
 if found then
  if previous.input_sha<>fingerprint then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('requestId',p_request,'result',previous.result,'snapshot',demo_desktop.snapshot(o,p_workspace));
 end if;
 if exists(select from demo_desktop.companies where owner_id=o and workspace_id=p_workspace and active) then perform demo_desktop.fail('already-shared');end if;
 if server_revision is distinct from p_input->>'serverRevision' then perform demo_desktop.fail('conflict');end if;
 insert into demo_desktop.companies(owner_id,workspace_id,active,source_revision,source_sha256) values(o,p_workspace,false,server_revision,p_input->>'sourceSha256') on conflict(owner_id,workspace_id) do update set source_revision=excluded.source_revision,source_sha256=excluded.source_sha256;
 if exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace) or exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace) then perform demo_desktop.fail('conflict');end if;
 for row_value in select value from jsonb_array_elements(source->'customers') loop
  cid:=demo_desktop.import_id(row_value,'id');
  if row_value-array['id','name','phone','phone_raw','phone_ok','memo','special_notes','registration_status','deleted_at','created_at']<>'{}' or coalesce(row_value->>'registration_status','registered') not in ('registered','declined') then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(o,p_workspace,cid,row_value-'id');
 end loop;
 for row_value in select value from jsonb_array_elements(source->'graves') loop
  gid:=demo_desktop.import_id(row_value,'id');cid:=case when row_value->>'customer_id' is not null then demo_desktop.import_id(row_value,'customer_id') end;
  if row_value-array['id','customer_id','address','gubun','seq','contract_year','gisu','pyeong','note','is_managed','business_region','extra_json','is_active','source_row','deleted_at','created_at']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(o,p_workspace,gid,cid,row_value-array['id','customer_id']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'payments') loop
  if row_value-array['id','grave_id','year','amount','kind','paid_at','method','source','note']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.payments(owner_id,workspace_id,id,grave_id,year,kind,amount,data) values(o,p_workspace,demo_desktop.import_id(row_value,'id'),demo_desktop.import_id(row_value,'grave_id'),(row_value->>'year')::integer,row_value->>'kind',(row_value->>'amount')::bigint,row_value-array['id','grave_id','year','kind','amount']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'annualWork') loop
  if row_value-array['id','year','customer_id','grave_id','status','notes','deadline','version','deleted_at']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'grave_id' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'grave_id')::bigint and customer_id=(row_value->>'customer_id')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,version,deleted_at,data) values(o,p_workspace,(row_value->>'id')::uuid,(row_value->>'year')::integer,demo_desktop.import_id(row_value,'customer_id'),case when row_value->>'grave_id' is not null then demo_desktop.import_id(row_value,'grave_id') end,row_value->>'status',coalesce((row_value->>'version')::bigint,1),row_value->>'deleted_at',row_value-array['id','year','customer_id','grave_id','status','version','deleted_at']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'workRows') loop
  if coalesce(row_value->>'key','')='' then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'customerId' is not null and not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=(row_value->>'customerId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'graveId' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint and (row_value->>'customerId' is null or customer_id=(row_value->>'customerId')::bigint)) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.work_rows values(o,p_workspace,row_value->>'key',row_value);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'locations') loop insert into demo_desktop.locations values(o,p_workspace,demo_desktop.import_id(row_value,'id'),row_value);end loop;
 for row_value in select value from jsonb_array_elements(source->'earthVersions') loop
  if row_value->'manifest'->>'workspaceId' is distinct from p_workspace::text or row_value->'manifest'->>'versionId' is distinct from row_value->>'versionId' or row_value->'manifest'->>'graveId' is distinct from row_value->>'graveId' or not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.imported_earth_versions values(o,p_workspace,(row_value->>'versionId')::uuid,demo_desktop.import_id(row_value,'graveId'),row_value);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'earthLinks') loop
  if row_value->>'versionId' is not null and not exists(select from demo_desktop.imported_earth_versions where owner_id=o and workspace_id=p_workspace and version_id=(row_value->>'versionId')::uuid and grave_id=(row_value->>'graveId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'versionId' is not null then
   if not exists(select from public.demo_earth_assets a join demo_desktop.imported_earth_versions v on v.owner_id=a.owner_id and v.workspace_id=a.workspace_id and v.version_id=a.version_id where a.owner_id=o and a.workspace_id=p_workspace and a.version_id=(row_value->>'versionId')::uuid and a.state='ready' and a.retired_at is null and a.manifest=v.data->'manifest') then perform demo_desktop.fail('earth-not-ready');end if;
   row_value:=jsonb_set(row_value,'{summary,asset}',(select jsonb_build_object('versionId',v.version_id,'sha256',v.data->'manifest'->'sha256','size',v.data->'manifest'->'size','sourceFile',v.data->'manifest'->'sourceFile','state','ready') from demo_desktop.imported_earth_versions v where v.owner_id=o and v.workspace_id=p_workspace and v.version_id=(row_value->>'versionId')::uuid));
  end if;
  insert into demo_desktop.earth_links values(o,p_workspace,demo_desktop.import_id(row_value,'graveId'),(row_value->>'versionId')::uuid,row_value->'summary');
 end loop;
 foreach k in array array['customers','graves','payments'] loop
  execute format('select coalesce(max(id),0) from demo_desktop.%I where owner_id=$1 and workspace_id=$2',k) into maximum using o,p_workspace;
  if jsonb_typeof(source->'idCounters'->k) is distinct from 'number' or (source->'idCounters'->>k)::numeric<>trunc((source->'idCounters'->>k)::numeric) then perform demo_desktop.fail('invalid-input');end if;
  counter:=(source->'idCounters'->>k)::bigint;if counter<maximum or counter>9007199254740991 then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.id_counters values(o,p_workspace,k,counter) on conflict(owner_id,workspace_id,name) do update set high_water=greatest(demo_desktop.id_counters.high_water,excluded.high_water);
 end loop;
 -- Events remain additive and keep their original IDs. Current customer changes never rewrite history.
 for row_value in select value from jsonb_array_elements(source->'events') order by case value->>'kind' when 'claim_created' then 0 else 1 end,value->>'at',value->>'id' loop
  if row_value->>'workspaceId' is distinct from p_workspace::text then perform demo_desktop.fail('invalid-input');end if;
  select * into event_value from public.demo_events where owner_id=o and id=(row_value->>'id')::uuid;
  if found then
   if event_value.workspace_id<>p_workspace or event_value.kind is distinct from row_value->>'kind' or event_value.payload is distinct from row_value->'payload' or event_value.happened_at is distinct from (row_value->>'at')::timestamptz then perform demo_desktop.fail('conflict');end if;
  else insert into public.demo_events(owner_id,workspace_id,id,kind,happened_at,payload) values(o,p_workspace,(row_value->>'id')::uuid,row_value->>'kind',(row_value->>'at')::timestamptz,row_value->'payload');end if;
 end loop;
 update demo_desktop.companies set active=true where owner_id=o and workspace_id=p_workspace;
 if to_regprocedure('demo_desktop.refresh_sent_amounts(uuid,uuid)') is not null then perform demo_desktop.refresh_sent_amounts(o,p_workspace);end if;
 perform demo_desktop.refresh_projection(o,p_workspace);
 result:=jsonb_build_object('imported',true,'sourceSha256',p_input->>'sourceSha256','serverRevision',p_input->>'serverRevision');
 insert into demo_desktop.requests values(o,p_workspace,a,p_request,gen_random_uuid(),fingerprint,result,clock_timestamp());
 return jsonb_build_object('requestId',p_request,'result',result,'snapshot',demo_desktop.snapshot(o,p_workspace));
end $$;

create or replace function demo_desktop.import_transfer(p_workspace uuid,p_request uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor(p_workspace);a uuid:=auth.uid();source jsonb;row_value jsonb;previous demo_desktop.requests;fingerprint text;result jsonb;server_revision text;k text;maximum bigint;counter bigint;cid bigint;gid bigint;event_value public.demo_events;begin
 if a<>o then perform demo_desktop.fail('access-denied');end if;
 if p_request is null or jsonb_typeof(p_input) is distinct from 'object' or p_input-array['protocol','sourceSha256','transferSha256','transferJson','serverRevision']<>'{}' or p_input->>'protocol' is distinct from '2' or jsonb_typeof(p_input->'transferJson') is distinct from 'string' or octet_length(p_input->>'transferJson')>20000000 or coalesce(p_input->>'sourceSha256','')!~'^[a-f0-9]{64}$' or coalesce(p_input->>'transferSha256','')!~'^[a-f0-9]{64}$' or jsonb_typeof(p_input->'serverRevision') is distinct from 'string' then perform demo_desktop.fail('invalid-input');end if;
 if encode(sha256(convert_to(p_input->>'transferJson','UTF8')),'hex')<>p_input->>'transferSha256' then perform demo_desktop.fail('source-mismatch');end if;
 begin source:=(p_input->>'transferJson')::jsonb;exception when others then perform demo_desktop.fail('invalid-input');end;
 source:=demo_desktop.transfer_payload(source);
 select revision into server_revision from public.demo_catalogs where owner_id=o and workspace_id=p_workspace for no key update;
 perform demo_desktop.lock_actor(p_workspace,o);
 fingerprint:=encode(sha256(convert_to('import:'||p_input::text,'UTF8')),'hex');
 select * into previous from demo_desktop.requests where owner_id=o and workspace_id=p_workspace and actor_id=a and request_id=p_request;
 if found then
  if previous.input_sha<>fingerprint then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('requestId',p_request,'result',previous.result,'snapshot',demo_desktop.snapshot(o,p_workspace));
 end if;
 if exists(select from demo_desktop.companies where owner_id=o and workspace_id=p_workspace and active) then perform demo_desktop.fail('already-shared');end if;
 if server_revision is distinct from p_input->>'serverRevision' then perform demo_desktop.fail('conflict');end if;
 insert into demo_desktop.companies(owner_id,workspace_id,active,source_revision,source_sha256) values(o,p_workspace,false,server_revision,p_input->>'sourceSha256') on conflict(owner_id,workspace_id) do update set source_revision=excluded.source_revision,source_sha256=excluded.source_sha256;
 if exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace) or exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace) then perform demo_desktop.fail('conflict');end if;
 for row_value in select value from jsonb_array_elements(source->'customers') loop
  cid:=demo_desktop.import_id(row_value,'id');
  if row_value-array['id','name','phone','phone_raw','phone_ok','memo','special_notes','registration_status','deleted_at','created_at']<>'{}' or coalesce(row_value->>'registration_status','registered') not in ('registered','declined') then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.customers(owner_id,workspace_id,id,data) values(o,p_workspace,cid,row_value-'id');
 end loop;
 for row_value in select value from jsonb_array_elements(source->'graves') loop
  gid:=demo_desktop.import_id(row_value,'id');cid:=case when row_value->>'customer_id' is not null then demo_desktop.import_id(row_value,'customer_id') end;
  if row_value-array['id','customer_id','address','gubun','seq','contract_year','gisu','pyeong','note','is_managed','business_region','is_active','deleted_at','created_at']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.graves(owner_id,workspace_id,id,customer_id,data) values(o,p_workspace,gid,cid,row_value-array['id','customer_id']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'payments') loop
  if row_value-array['id','grave_id','year','amount','kind','paid_at','method','source','note']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.payments(owner_id,workspace_id,id,grave_id,year,kind,amount,data) values(o,p_workspace,demo_desktop.import_id(row_value,'id'),demo_desktop.import_id(row_value,'grave_id'),(row_value->>'year')::integer,row_value->>'kind',(row_value->>'amount')::bigint,row_value-array['id','grave_id','year','kind','amount']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'annualWork') loop
  if row_value-array['id','year','customer_id','grave_id','status','notes','deadline','version','deleted_at']<>'{}' then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'grave_id' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'grave_id')::bigint and customer_id=(row_value->>'customer_id')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.annual_work(owner_id,workspace_id,id,year,customer_id,grave_id,status,version,deleted_at,data) values(o,p_workspace,(row_value->>'id')::uuid,(row_value->>'year')::integer,demo_desktop.import_id(row_value,'customer_id'),case when row_value->>'grave_id' is not null then demo_desktop.import_id(row_value,'grave_id') end,row_value->>'status',coalesce((row_value->>'version')::bigint,1),row_value->>'deleted_at',row_value-array['id','year','customer_id','grave_id','status','version','deleted_at']);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'workRows') loop
  if coalesce(row_value->>'key','')='' then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'customerId' is not null and not exists(select from demo_desktop.customers where owner_id=o and workspace_id=p_workspace and id=(row_value->>'customerId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'graveId' is not null and not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint and (row_value->>'customerId' is null or customer_id=(row_value->>'customerId')::bigint)) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.work_rows values(o,p_workspace,row_value->>'key',row_value);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'locations') loop insert into demo_desktop.locations values(o,p_workspace,demo_desktop.import_id(row_value,'id'),row_value);end loop;
 for row_value in select value from jsonb_array_elements(source->'earthVersions') loop
  if row_value->'manifest'->>'workspaceId' is distinct from p_workspace::text or row_value->'manifest'->>'versionId' is distinct from row_value->>'versionId' or row_value->'manifest'->>'graveId' is distinct from row_value->>'graveId' or not exists(select from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=(row_value->>'graveId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.imported_earth_versions values(o,p_workspace,(row_value->>'versionId')::uuid,demo_desktop.import_id(row_value,'graveId'),row_value);
 end loop;
 for row_value in select value from jsonb_array_elements(source->'earthLinks') loop
  if row_value->>'versionId' is not null and not exists(select from demo_desktop.imported_earth_versions where owner_id=o and workspace_id=p_workspace and version_id=(row_value->>'versionId')::uuid and grave_id=(row_value->>'graveId')::bigint) then perform demo_desktop.fail('invalid-input');end if;
  if row_value->>'versionId' is not null then
   if not exists(select from public.demo_earth_assets a join demo_desktop.imported_earth_versions v on v.owner_id=a.owner_id and v.workspace_id=a.workspace_id and v.version_id=a.version_id where a.owner_id=o and a.workspace_id=p_workspace and a.version_id=(row_value->>'versionId')::uuid and a.state='ready' and a.retired_at is null and a.manifest=v.data->'manifest') then perform demo_desktop.fail('earth-not-ready');end if;
   row_value:=jsonb_set(row_value,'{summary,asset}',(select jsonb_build_object('versionId',v.version_id,'sha256',v.data->'manifest'->'sha256','size',v.data->'manifest'->'size','sourceFile',v.data->'manifest'->'sourceFile','state','ready') from demo_desktop.imported_earth_versions v where v.owner_id=o and v.workspace_id=p_workspace and v.version_id=(row_value->>'versionId')::uuid));
  end if;
  insert into demo_desktop.earth_links values(o,p_workspace,demo_desktop.import_id(row_value,'graveId'),(row_value->>'versionId')::uuid,row_value->'summary');
 end loop;
 foreach k in array array['customers','graves','payments'] loop
  execute format('select coalesce(max(id),0) from demo_desktop.%I where owner_id=$1 and workspace_id=$2',k) into maximum using o,p_workspace;
  if jsonb_typeof(source->'idCounters'->k) is distinct from 'number' or (source->'idCounters'->>k)::numeric<>trunc((source->'idCounters'->>k)::numeric) then perform demo_desktop.fail('invalid-input');end if;
  counter:=(source->'idCounters'->>k)::bigint;if counter<maximum or counter>9007199254740991 then perform demo_desktop.fail('invalid-input');end if;
  insert into demo_desktop.id_counters values(o,p_workspace,k,counter) on conflict(owner_id,workspace_id,name) do update set high_water=greatest(demo_desktop.id_counters.high_water,excluded.high_water);
 end loop;
 -- Events remain additive and keep their original IDs. Current customer changes never rewrite history.
 for row_value in select value from jsonb_array_elements(source->'events') order by case value->>'kind' when 'claim_created' then 0 else 1 end,value->>'at',value->>'id' loop
  if row_value->>'workspaceId' is distinct from p_workspace::text then perform demo_desktop.fail('invalid-input');end if;
  select * into event_value from public.demo_events where owner_id=o and id=(row_value->>'id')::uuid;
  if found then
   if event_value.workspace_id<>p_workspace or event_value.kind is distinct from row_value->>'kind' or event_value.payload is distinct from row_value->'payload' or event_value.happened_at is distinct from (row_value->>'at')::timestamptz then perform demo_desktop.fail('conflict');end if;
  else insert into public.demo_events(owner_id,workspace_id,id,kind,happened_at,payload) values(o,p_workspace,(row_value->>'id')::uuid,row_value->>'kind',(row_value->>'at')::timestamptz,row_value->'payload');end if;
 end loop;
 update demo_desktop.companies set active=true where owner_id=o and workspace_id=p_workspace;
 if to_regprocedure('demo_desktop.refresh_sent_amounts(uuid,uuid)') is not null then perform demo_desktop.refresh_sent_amounts(o,p_workspace);end if;
 perform demo_desktop.refresh_projection(o,p_workspace);
 result:=jsonb_build_object('imported',true,'sourceSha256',p_input->>'sourceSha256','transferSha256',p_input->>'transferSha256','serverRevision',p_input->>'serverRevision');
 insert into demo_desktop.requests values(o,p_workspace,a,p_request,gen_random_uuid(),fingerprint,result,clock_timestamp());
 return jsonb_build_object('requestId',p_request,'result',result,'snapshot',demo_desktop.snapshot(o,p_workspace));
end $$;

create or replace function public.demo_desktop_import(p_workspace uuid,p_request uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare o uuid:=demo_desktop.assert_actor(p_workspace);begin
 if p_input->>'protocol'='2' then return demo_desktop.import_transfer(p_workspace,p_request,p_input);end if;
 if demo_desktop.privacy_enabled(o,p_workspace) then perform demo_desktop.fail('client-update-required');end if;
 return demo_desktop.import_legacy(p_workspace,p_request,p_input);
end $$;
revoke all on all functions in schema demo_desktop from public,anon,authenticated,service_role;
revoke all on function public.demo_desktop_import(uuid,uuid,jsonb) from public,anon,service_role;
grant execute on function public.demo_desktop_import(uuid,uuid,jsonb) to authenticated;

-- Financial originals stay internal. No foreign key below cascades from a customer/grave.
create table if not exists demo_desktop.privacy_state(
 owner_id uuid not null,workspace_id uuid not null,enabled boolean not null default false,
 epoch uuid not null default gen_random_uuid(),protocol integer not null default 2 check(protocol=2),
 revision bigint not null default 1,activated_at timestamptz,
 primary key(owner_id,workspace_id),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
create table if not exists demo_desktop.financial_basis(
 owner_id uuid not null,workspace_id uuid not null,id bigint not null,customer_id bigint,grave_id bigint not null,
 year integer not null,kind text not null,amount bigint not null check(amount between 0 and 9007199254740991),
 data jsonb not null,record_sha256 text not null check(record_sha256~'^[a-f0-9]{64}$'),
 policy_state text not null default 'unclassified' check(policy_state in ('unclassified','classified','expired')),
 archived_at timestamptz not null default clock_timestamp(),primary key(owner_id,workspace_id,id),
 foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
create table if not exists demo_desktop.financial_evidence(
 owner_id uuid not null,workspace_id uuid not null,source_kind text not null check(source_kind in ('event','receipt')),
 source_id text not null,event_kind text,customer_id bigint,grave_id bigint,claim_id uuid,year integer,
 record_sha256 text not null check(record_sha256~'^[a-f0-9]{64}$'),retained_fields text[] not null,
 policy_kind text not null,policy_revision bigint,anchor_at timestamptz,hold_reason text,
 state text not null default 'unclassified' check(state in ('unclassified','classified','expired')),
 primary key(owner_id,workspace_id,source_kind,source_id),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
create table if not exists demo_desktop.evidence_access_log(
 id uuid primary key default gen_random_uuid(),owner_id uuid not null,workspace_id uuid not null,
 actor_id uuid not null,auth_session_id uuid not null,evidence_id text not null,purpose text not null,
 accessed_at timestamptz not null default clock_timestamp(),
 foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
create table if not exists demo_desktop.financial_counterparts(
 owner_id uuid not null,workspace_id uuid not null,customer_id bigint not null,name text not null,grave_ids bigint[] not null,
 record_sha256 text not null,policy_state text not null default 'unclassified',archived_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,workspace_id,customer_id),foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
do $$declare t text;begin foreach t in array array['privacy_state','financial_basis','financial_evidence','evidence_access_log','financial_counterparts'] loop
 execute format('alter table demo_desktop.%I enable row level security',t);
 execute format('revoke all on demo_desktop.%I from public,anon,authenticated,service_role,demo_desktop_writer',t);
end loop;end $$;

create or replace function demo_desktop.canonical_json(p jsonb) returns text language plpgsql immutable set search_path='' as $$declare result text;begin
 if jsonb_typeof(p)='object' then select '{'||coalesce(string_agg(to_jsonb(key)::text||':'||demo_desktop.canonical_json(value),',' order by key collate "C"),'')||'}' into result from jsonb_each(p);return result;
 elsif jsonb_typeof(p)='array' then select '['||coalesce(string_agg(demo_desktop.canonical_json(value),',' order by n),'')||']' into result from jsonb_array_elements(p) with ordinality a(value,n);return result;
 elsif jsonb_typeof(p)='number' and (p#>>'{}')::numeric=trunc((p#>>'{}')::numeric) then return trunc((p#>>'{}')::numeric)::text;
 else return p::text;end if;
end $$;
create or replace function demo_desktop.financial_digest(p jsonb) returns text language sql immutable set search_path='' as $$select encode(sha256(convert_to(demo_desktop.canonical_json(p),'UTF8')),'hex')$$;
create or replace function demo_desktop.event_document(p public.demo_events) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',p.id,'workspaceId',p.workspace_id,'kind',p.kind,'at',to_char(p.happened_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'payload',p.payload)$$;
create or replace function demo_desktop.receipt_document(p public.demo_bank_receipts) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',p.id,'amount',p.amount,'payer',p.payer,'bankAt',p.bank_at,'receivedAt',p.received_at,'excerpt',p.excerpt,'fingerprint',p.fingerprint)$$;
create or replace function demo_desktop.financial_year(p_owner uuid,p_workspace uuid,p_claim public.demo_events) returns integer language sql stable set search_path='' as $$
 select coalesce((select a.year from demo_desktop.annual_work a where a.owner_id=p_owner and a.workspace_id=p_workspace and 'annual:'||a.id::text=p_claim.payload->>'taskKey'),
 (select e.year from demo_desktop.financial_evidence e where e.owner_id=p_owner and e.workspace_id=p_workspace and e.source_kind='event' and e.source_id=p_claim.id::text),extract(year from p_claim.happened_at at time zone 'UTC')::integer)
$$;
create or replace function demo_desktop.financial_amount(p_amount numeric) returns bigint language plpgsql immutable set search_path='' as $$begin
 if p_amount is null or p_amount<0 or p_amount>9007199254740991 or p_amount<>trunc(p_amount) then perform demo_desktop.fail('invalid-input');end if;return p_amount::bigint;
end $$;
create or replace function demo_desktop.financial_summary(p_owner uuid,p_workspace uuid) returns jsonb language plpgsql stable set search_path='' as $$declare result jsonb;ep uuid;gen uuid;hd bigint;begin
 select epoch into ep from demo_desktop.privacy_state where owner_id=p_owner and workspace_id=p_workspace;
 select generation,head into gen,hd from public.demo_sync_state where owner_id=p_owner and workspace_id=p_workspace;
 with claims as (
  select c.*,demo_desktop.financial_amount(coalesce((select sum((p.payload->>'amount')::numeric) from public.demo_events p where p.owner_id=p_owner and p.workspace_id=p_workspace and p.kind='payment_recorded' and p.payload->>'claimId'=c.id::text and not exists(select from public.demo_events v where v.owner_id=p_owner and v.workspace_id=p_workspace and v.kind='payment_voided' and v.payload->>'claimId'=c.id::text and v.payload->>'paymentId'=p.id::text)),0)) paid,
  exists(select from public.demo_events d where d.owner_id=p_owner and d.workspace_id=p_workspace and d.payload->>'claimId'=c.id::text and (d.kind='dispatch_confirmed' or (d.kind='dispatch_result' and d.payload->>'status'='sent'))) sent,
  exists(select from public.demo_events d where d.owner_id=p_owner and d.workspace_id=p_workspace and d.payload->>'claimId'=c.id::text and d.kind='claim_deleted') deleted
  from public.demo_events c where c.owner_id=p_owner and c.workspace_id=p_workspace and c.kind='claim_created'
 ),basis as (
  select distinct on (id) * from (
   select p.id,g.customer_id,p.grave_id,p.year,p.kind,p.amount,0 priority from demo_desktop.payments p join demo_desktop.graves g using(owner_id,workspace_id) where p.owner_id=p_owner and p.workspace_id=p_workspace and g.id=p.grave_id
   union all select id,customer_id,grave_id,year,kind,amount,1 from demo_desktop.financial_basis where owner_id=p_owner and workspace_id=p_workspace and policy_state<>'expired'
  ) b order by id,priority
 ) select jsonb_build_object('format','demo-financial-view','version',1,'workspaceId',p_workspace,'privacyEpoch',ep,'generation',gen,'head',coalesce(hd,0),
 'claims',(select coalesce(jsonb_agg(jsonb_build_object(
  'id',c.id,'at',to_char(c.happened_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'customerId',(c.payload->>'customerId')::bigint,'graveId',(c.payload->>'graveId')::bigint,'reportId',c.payload->'reportId','taskKey',coalesce(c.payload->>'taskKey',''),'year',demo_desktop.financial_year(p_owner,p_workspace,row(c.owner_id,c.workspace_id,c.id,c.kind,c.happened_at,c.payload)::public.demo_events),
  'amount',(c.payload->>'amount')::bigint,'paidAmount',c.paid,'balance',(c.payload->>'amount')::bigint-c.paid,'sent',c.sent,'deleted',c.deleted,
  'deliveryStatus',(select d.payload->>'status' from public.demo_events d where d.owner_id=p_owner and d.workspace_id=p_workspace and d.payload->>'claimId'=c.id::text and d.kind='dispatch_result' order by d.happened_at desc,d.id desc limit 1),
  'completionDeliveryStatus',(select d.payload->>'status' from public.demo_events d where d.owner_id=p_owner and d.workspace_id=p_workspace and d.payload->>'claimId'=c.id::text and d.kind='completion_result' order by d.happened_at desc,d.id desc limit 1),
  'completionSent',exists(select from public.demo_events d where d.owner_id=p_owner and d.workspace_id=p_workspace and d.payload->>'claimId'=c.id::text and (d.kind='completion_confirmed' or (d.kind='completion_result' and d.payload->>'status'='sent'))),
  'completionConfirmed',exists(select from public.demo_events d where d.owner_id=p_owner and d.workspace_id=p_workspace and d.payload->>'claimId'=c.id::text and d.kind='completion_confirmed'),
  'composerOpened',exists(select from public.demo_events d where d.owner_id=p_owner and d.workspace_id=p_workspace and d.payload->>'claimId'=c.id::text and d.kind='composer_opened'),
  'paymentStatus',case when c.paid=0 then '미입금' when c.paid<(c.payload->>'amount')::bigint then '일부 입금' when c.paid=(c.payload->>'amount')::bigint then '입금 완료' else '초과 입금' end,
  'events',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'kind',d.kind,'at',to_char(d.happened_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'amount',d.payload->'amount','claimId',c.id,'paymentId',d.payload->'paymentId','attemptId',d.payload->'attemptId','status',d.payload->'status') order by d.happened_at,d.id),'[]') from public.demo_events d where d.owner_id=p_owner and d.workspace_id=p_workspace and d.payload->>'claimId'=c.id::text)
 ) order by c.happened_at desc,c.id desc),'[]') from claims c),
 'basis',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'customerId',customer_id,'graveId',grave_id,'year',year,'kind',kind,'amount',amount) order by id),'[]') from basis),
 'receipts',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'amount',r.amount,'bankAt',r.bank_at,'receivedAt',r.received_at,'status',r.status,'reasonCode',r.status,'claimId',r.claim_id,'paymentId',r.payment_id) order by r.received_at desc,r.id),'[]') from public.demo_bank_receipts r where r.owner_id=p_owner and r.workspace_id=p_workspace)
 ) into result;return result;
end $$;

create or replace function demo_desktop.archive_financial(p_owner uuid,p_workspace uuid,p_subject jsonb) returns jsonb language plpgsql set search_path='' as $$declare ids bigint[];cid bigint:=(p_subject->>'customerId')::bigint;r record;doc jsonb;h text;old_sha text;claims uuid[];bc bigint:=0;ec bigint:=0;rc bigint:=0;total numeric:=0;claim public.demo_events;ev public.demo_events;br public.demo_bank_receipts;yr integer;begin
 perform demo_desktop.lock_company(p_owner,p_workspace);
 ids:=array(select value::bigint from jsonb_array_elements_text(p_subject->'graveIds'));
 for r in select p.*,g.customer_id from demo_desktop.payments p join demo_desktop.graves g on g.owner_id=p.owner_id and g.workspace_id=p.workspace_id and g.id=p.grave_id where p.owner_id=p_owner and p.workspace_id=p_workspace and p.grave_id=any(ids) loop
  doc:=jsonb_build_object('id',r.id,'customerId',r.customer_id,'graveId',r.grave_id,'year',r.year,'kind',r.kind,'amount',r.amount,'source',r.data->'source','note',r.data->'note','paid_at',r.data->'paid_at','method',r.data->'method');h:=demo_desktop.financial_digest(doc);
  select record_sha256 into old_sha from demo_desktop.financial_basis where owner_id=p_owner and workspace_id=p_workspace and id=r.id;
  if found and old_sha<>h then perform demo_desktop.fail('privacy-conflict');end if;
  insert into demo_desktop.financial_basis(owner_id,workspace_id,id,customer_id,grave_id,year,kind,amount,data,record_sha256) values(p_owner,p_workspace,r.id,r.customer_id,r.grave_id,r.year,r.kind,r.amount,doc,h) on conflict do nothing;
  bc:=bc+1;total:=total+r.amount;
 end loop;
 select array_agg(id) into claims from public.demo_events where owner_id=p_owner and workspace_id=p_workspace and kind='claim_created' and ((payload->>'customerId')::bigint=cid or (payload->>'graveId')::bigint=any(ids));
 if cid is not null and (coalesce(cardinality(claims),0)>0 or total>0) then
  insert into demo_desktop.financial_counterparts(owner_id,workspace_id,customer_id,name,grave_ids,record_sha256)
  select p_owner,p_workspace,cid,coalesce(data->>'name',''),ids,demo_desktop.financial_digest(jsonb_build_object('customerId',cid,'name',coalesce(data->>'name',''),'graveIds',to_jsonb(ids))) from demo_desktop.customers where owner_id=p_owner and workspace_id=p_workspace and id=cid
  on conflict(owner_id,workspace_id,customer_id) do nothing;
 end if;
 for ev in select e.* from public.demo_events e where e.owner_id=p_owner and e.workspace_id=p_workspace and (e.id=any(claims) or e.payload->>'claimId'=any(array(select unnest(claims)::text)) or (e.kind='task_linked' and ((e.payload->>'customerId')::bigint=cid or (e.payload->>'graveId')::bigint=any(ids)))) loop
  doc:=demo_desktop.event_document(ev);h:=demo_desktop.financial_digest(doc);
  if ev.kind='claim_created' then claim:=ev;else select * into claim from public.demo_events where owner_id=p_owner and workspace_id=p_workspace and id=(ev.payload->>'claimId')::uuid;end if;
  yr:=case when claim.id is not null then demo_desktop.financial_year(p_owner,p_workspace,claim) else extract(year from ev.happened_at at time zone 'UTC')::integer end;
  select record_sha256 into old_sha from demo_desktop.financial_evidence where owner_id=p_owner and workspace_id=p_workspace and source_kind='event' and source_id=ev.id::text;
  if found and old_sha<>h then perform demo_desktop.fail('privacy-conflict');end if;
  insert into demo_desktop.financial_evidence(owner_id,workspace_id,source_kind,source_id,event_kind,customer_id,grave_id,claim_id,year,record_sha256,retained_fields,policy_kind)
  values(p_owner,p_workspace,'event',ev.id::text,ev.kind,coalesce((claim.payload->>'customerId')::bigint,cid),coalesce((claim.payload->>'graveId')::bigint,(ev.payload->>'graveId')::bigint),claim.id,yr,h,array(select jsonb_object_keys(ev.payload)),'financial_event') on conflict do nothing;ec:=ec+1;
 end loop;
 for br in select * from public.demo_bank_receipts where owner_id=p_owner and workspace_id=p_workspace and claim_id=any(claims) loop
  h:=demo_desktop.financial_digest(demo_desktop.receipt_document(br));
  select record_sha256 into old_sha from demo_desktop.financial_evidence where owner_id=p_owner and workspace_id=p_workspace and source_kind='receipt' and source_id=br.id::text;
  if found and old_sha<>h then perform demo_desktop.fail('privacy-conflict');end if;
  insert into demo_desktop.financial_evidence(owner_id,workspace_id,source_kind,source_id,claim_id,record_sha256,retained_fields,policy_kind) values(p_owner,p_workspace,'receipt',br.id::text,br.claim_id,h,array['amount','payer','bankAt','receivedAt','excerpt','fingerprint'],'bank_receipt') on conflict do nothing;rc:=rc+1;
 end loop;
 return jsonb_build_object('basisCount',bc,'eventCount',ec,'receiptCount',rc,'basisTotal',demo_desktop.financial_amount(total));
end $$;

-- The amount summary behind the customer list is read data ('read'); 청구·입금 stays 'billing'.
create or replace function public.demo_desktop_financial_read(p_workspace uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare o uuid:=demo_desktop.assert_actor_for(p_workspace,'read');begin
 perform demo_desktop.transfer_keys(p_input,array['epoch','generation','cursor']);
 perform demo_desktop.lock_company(o,p_workspace);perform demo_desktop.lock_actor(p_workspace,o);
 insert into demo_desktop.privacy_state(owner_id,workspace_id) values(o,p_workspace) on conflict do nothing;
 return demo_desktop.financial_summary(o,p_workspace);
end $$;
create or replace function public.demo_desktop_financial_detail(p_workspace uuid,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare o uuid:=demo_desktop.assert_actor_for(p_workspace,'billing');eid text:=p_input->>'id';purpose text:=p_input->>'purpose';v jsonb;e public.demo_events;r public.demo_bank_receipts;begin
 perform demo_desktop.transfer_keys(p_input,array['id','purpose']);
 if purpose not in ('evidence','dispatch') or purpose is null or eid is null or length(eid)>200 then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);perform demo_desktop.lock_actor(p_workspace,o);
 if eid like 'event:%' then
  select * into e from public.demo_events where owner_id=o and workspace_id=p_workspace and id=substr(eid,7)::uuid;
  if not found then perform demo_desktop.fail('evidence-unavailable');end if;
  if purpose='dispatch' and (e.kind<>'claim_created' or not exists(select from demo_desktop.customers c where c.owner_id=o and c.workspace_id=p_workspace and c.id=(e.payload->>'customerId')::bigint and nullif(c.data->>'deleted_at','') is null and coalesce(c.data->>'registration_status','registered')<>'declined') or exists(select from public.demo_events d where d.owner_id=o and d.workspace_id=p_workspace and d.kind='claim_deleted' and d.payload->>'claimId'=e.id::text)) then perform demo_desktop.fail('dispatch-unavailable');end if;
  v:=jsonb_build_object('id',eid,'purpose',purpose,'state','available','event',demo_desktop.event_document(e));
 elsif eid like 'basis:%' and purpose='evidence' then
  select jsonb_build_object('id',eid,'purpose',purpose,'state','available','basis',data) into v from demo_desktop.financial_basis where owner_id=o and workspace_id=p_workspace and id=substr(eid,7)::bigint and policy_state<>'expired';
 elsif eid like 'receipt:%' and purpose='evidence' then
  select * into r from public.demo_bank_receipts where owner_id=o and workspace_id=p_workspace and id=substr(eid,9)::uuid;
  if found then v:=jsonb_build_object('id',eid,'purpose',purpose,'state','available','receipt',demo_desktop.receipt_document(r));end if;
 else perform demo_desktop.fail('invalid-input');end if;
 if v is null then perform demo_desktop.fail('evidence-unavailable');end if;
 perform set_config('response.headers','[{"Cache-Control":"no-store"}]',true);
 insert into demo_desktop.evidence_access_log(owner_id,workspace_id,actor_id,auth_session_id,evidence_id,purpose) values(o,p_workspace,auth.uid(),demo_desktop.auth_session(),eid,purpose);
 return v;
end $$;
