create policy projection_writer on demo_desktop.boundary_keys for all to demo_desktop_writer using(true) with check(true);

-- Only a Polygon has a key (a Point is a location, not a boundary). Anything unreadable has none.
create or replace function demo_desktop.boundary_key(g jsonb) returns text language plpgsql immutable set search_path='' as $$declare k text;begin
 if g is null or g->>'type' is distinct from 'Polygon' or jsonb_typeof(g->'coordinates'->0) is distinct from 'array' then return null;end if;
 with p as (
  select t.ord,round((t.e->>0)::numeric,6) x,round((t.e->>1)::numeric,6) y from jsonb_array_elements(g->'coordinates'->0) with ordinality t(e,ord)
 ),c as (
  -- The ring is closed (last point = first point); the closing point is not part of the key.
  select p.* from p where not (p.ord>1 and p.ord=(select max(ord) from p) and p.x=(select x from p where ord=1) and p.y=(select y from p where ord=1))
 ),n as (select count(*)::int cnt from c),
 d as (
  select c.ord,c.x,c.y,coalesce(lead(c.x) over (order by c.ord),first_value(c.x) over (order by c.ord)) nx,coalesce(lead(c.y) over (order by c.ord),first_value(c.y) over (order by c.ord)) ny from c
 ),a as (select coalesce(sum(d.x*d.ny-d.nx*d.y),0) area from d),
 o as (
  -- Always walk the ring counter-clockwise, starting from its lowest point.
  select d.x,d.y,case when (select area from a)>=0 then d.ord else (select cnt from n)+1-d.ord end pos from d
 ),s as (select o.pos spos from o order by o.x,o.y,o.pos limit 1)
 select md5(string_agg(o.x::text||','||o.y::text,';' order by (o.pos-(select spos from s)+(select cnt from n))%(select cnt from n))) into k from o where (select cnt from n)>=3;
 return k;
exception when others then return null;
end $$;

-- Keep the grave keys in step with the graves' location links (also covers imports and restores).
create or replace function demo_desktop.boundary_key_sync() returns trigger language plpgsql set search_path='' as $$declare k text;begin
 if tg_op in ('UPDATE','DELETE') then delete from demo_desktop.boundary_keys where owner_id=old.owner_id and workspace_id=old.workspace_id and kind='grave' and ref=old.grave_id::text;end if;
 if tg_op in ('INSERT','UPDATE') then
  k:=demo_desktop.boundary_key(new.data->'geometry');
  if k is not null then insert into demo_desktop.boundary_keys(owner_id,workspace_id,kind,ref,key) values(new.owner_id,new.workspace_id,'grave',new.grave_id::text,k) on conflict(owner_id,workspace_id,kind,ref) do update set key=excluded.key;end if;
 end if;
 return null;
end $$;
drop trigger if exists desktop_boundary_keys on demo_desktop.earth_links;
create trigger desktop_boundary_keys after insert or update or delete on demo_desktop.earth_links for each row execute function demo_desktop.boundary_key_sync();
-- Links that exist before this release.
insert into demo_desktop.boundary_keys(owner_id,workspace_id,kind,ref,key)
 select e.owner_id,e.workspace_id,'grave',e.grave_id::text,demo_desktop.boundary_key(e.data->'geometry') from demo_desktop.earth_links e where demo_desktop.boundary_key(e.data->'geometry') is not null
 on conflict(owner_id,workspace_id,kind,ref) do nothing;

-- Refuses a boundary that equals another grave's or another pending request's. p_grave / p_request:
-- the grave or request this boundary belongs to (it does not clash with itself). Deleted graves do
-- not count.
create or replace function demo_desktop.assert_boundary_free(p_owner uuid,p_workspace uuid,p_geometry jsonb,p_grave bigint,p_request uuid) returns void language plpgsql set search_path='' as $$declare k text:=demo_desktop.boundary_key(p_geometry);begin
 if k is null then return;end if;
 if exists(
  select from demo_desktop.boundary_keys b where b.owner_id=p_owner and b.workspace_id=p_workspace and b.key=k
   and not (b.kind='grave' and b.ref is not distinct from p_grave::text) and not (b.kind='request' and b.ref is not distinct from p_request::text)
   and (b.kind='request' or exists(select from demo_desktop.graves g where g.owner_id=b.owner_id and g.workspace_id=b.workspace_id and g.id=b.ref::bigint and nullif(g.data->>'deleted_at','') is null))
 ) then perform demo_desktop.fail('duplicate-boundary');end if;
end $$;

-- Send one registration for review. A retry of the same request id with the same content is
-- accepted again without a second row; the answer never says what happened to the request.
drop function if exists public.demo_desktop_registration_request(uuid,uuid,jsonb);
drop function if exists public.demo_desktop_registration_request(uuid,uuid,jsonb,text);
-- p_files: the request carries its location files (uploaded and finished under this request id).
-- They keep the grave number that was reserved under p_draft; the reservation is used up here.
create or replace function public.demo_desktop_registration_request(p_workspace uuid,p_request uuid,p_values jsonb,p_status text default 'registered',p_draft uuid default null,p_files boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;a uuid:=auth.uid();v jsonb;fp text;previous demo_desktop.registration_requests;who text;gid bigint;pf demo_desktop.registration_request_files;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'register-request');
 if p_request is null or p_status is null or p_status not in ('registered','declined') or jsonb_typeof(p_values) is distinct from 'object' or octet_length(p_values::text)>200000 or p_files is null or (p_files and p_draft is null) then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);
 perform demo_desktop.lock_actor(p_workspace,o);
 v:=demo_desktop.registration_values(p_values);
 if not exists(select from jsonb_each(v) where value<>'null'::jsonb and (key<>'isManaged' or value='1'::jsonb)) then perform demo_desktop.fail('invalid-input');end if;
 fp:=encode(sha256(convert_to(case when p_status='declined' then 'declined:'||v::text else v::text end||case when p_files then ':location' else '' end,'UTF8')),'hex');
 select * into previous from demo_desktop.registration_requests where owner_id=o and workspace_id=p_workspace and id=p_request;
 if found then
  if previous.requester_id<>a or previous.input_sha<>fp then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('requestId',p_request,'received',true);
 end if;
 if (select count(*) from demo_desktop.registration_requests where owner_id=o and workspace_id=p_workspace and requester_id=a and status='pending')>=200 then perform demo_desktop.fail('too-many-requests');end if;
 if p_files then
  -- Only finished files of this sender under this request id; the number is the one reserved for them.
  select * into pf from demo_desktop.registration_request_files where owner_id=o and workspace_id=p_workspace and request_id=p_request and actor_id=a and state='ready';
  if not found then perform demo_desktop.fail('invalid-input');end if;
  gid:=demo_desktop.reserved_grave(o,p_workspace,p_draft::text,true);
  if gid is distinct from pf.grave_id then perform demo_desktop.fail('invalid-input');end if;
 end if;
 select coalesce(nullif(btrim(display_name),''),login_id) into who from public.demo_members where user_id=a;
 insert into demo_desktop.registration_requests(owner_id,workspace_id,id,requester_id,requester_name,input_sha,input,registration_status,reserved_grave_id,has_location) values(o,p_workspace,p_request,a,coalesce(who,''),fp,v,p_status,gid,p_files);
 return jsonb_build_object('requestId',p_request,'received',true);
end $$;
revoke all on function public.demo_desktop_registration_request(uuid,uuid,jsonb,text,uuid,boolean) from public,anon,service_role;
grant execute on function public.demo_desktop_registration_request(uuid,uuid,jsonb,text,uuid,boolean) to authenticated;

-- The upload function asks this who is sending location files for a review request. Only the
-- roles that send requests (office, sales) pass; masters register directly.
create or replace function public.demo_desktop_request_access(p_workspace uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare o uuid;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'register-request');
 return jsonb_build_object('id',auth.uid(),'ownerId',o,'workspaceId',p_workspace,'role',demo_desktop.actor_role(p_workspace));
end $$;
revoke all on function public.demo_desktop_request_access(uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_request_access(uuid) to authenticated;

-- The upload function's own step (service role). begin: file the request's files under review/ and
-- reserve their keys once; get / publish: read it back or mark the upload finished. The grave number
-- must be the one reserved for this sender under the draft.
create or replace function public.demo_desktop_request_files(p_owner uuid,p_workspace uuid,p_actor uuid,p_action text,p_input jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r demo_desktop.registration_request_files;m jsonb;rid uuid;gid bigint;ext text;base text;stage text;draft uuid;arole text;rstatus text;begin
 perform demo_desktop.lock_company(p_owner,p_workspace);
 if p_action not in ('begin','get','publish','read','discard-keys','discard','sweep') then perform demo_desktop.fail('invalid-input');end if;
 select mb.role into arole from public.demo_members mb where mb.user_id=p_actor and mb.owner_id=p_owner and mb.workspace_id=p_workspace and mb.active;
 if arole is null and p_actor=p_owner and not exists(select from public.demo_members where user_id=p_actor) then arole:='owner';end if;
 -- Senders (office, sales) file their own request's files; masters read, and clear, them for the review.
 if not demo_desktop.role_allows(arole,case when p_action in ('begin','get','publish') then 'register-request' else 'register' end) then perform demo_desktop.fail('access-denied');end if;
 -- Step 4-5: files that are no longer needed. Those of a request that was approved or rejected, and
 -- unfinished uploads whose request never came (older than 2 days). A master removes them one by one
 -- with discard-keys / discard.
 if p_action='sweep' then
  perform demo_desktop.transfer_keys(p_input,array[]::text[]);
  return jsonb_build_object('requestIds',(select coalesce(jsonb_agg(x.request_id),'[]'::jsonb) from (
   select f.request_id from demo_desktop.registration_request_files f left join demo_desktop.registration_requests q on q.owner_id=f.owner_id and q.workspace_id=f.workspace_id and q.id=f.request_id
   where f.owner_id=p_owner and f.workspace_id=p_workspace and ((q.id is not null and q.status<>'pending') or (q.id is null and f.created_at<clock_timestamp()-interval '2 days'))
   order by f.created_at limit 20) x));
 end if;
 perform demo_desktop.transfer_keys(p_input,case when p_action='begin' then array['requestId','draftId','manifest'] else array['requestId'] end);
 rid:=(p_input->>'requestId')::uuid;
 select * into r from demo_desktop.registration_request_files where owner_id=p_owner and workspace_id=p_workspace and request_id=rid for update;
 if p_action in ('read','discard-keys','discard') then
  select status into rstatus from demo_desktop.registration_requests where owner_id=p_owner and workspace_id=p_workspace and id=rid;
  -- No request row: only an old unfinished upload may be cleared (the sender may still be sending a fresh one).
  if (rstatus is null and (p_action='read' or r.request_id is null or r.created_at>=clock_timestamp()-interval '2 days')) or (p_action='read' and (rstatus<>'pending' or r.request_id is null or r.state<>'ready')) or (p_action<>'read' and rstatus='pending') then perform demo_desktop.fail('invalid-input');end if;
  if p_action='discard' then
   delete from demo_desktop.stored_objects where owner_id=p_owner and workspace_id=p_workspace and ref_kind='request' and ref_id=rid;
   delete from demo_desktop.registration_request_files where owner_id=p_owner and workspace_id=p_workspace and request_id=rid;
   delete from demo_desktop.boundary_keys where owner_id=p_owner and workspace_id=p_workspace and kind='request' and ref=rid::text;
   return jsonb_build_object('discarded',true);
  end if;
  if r.request_id is null then return jsonb_build_object('versionId',rid,'state','gone','keys','{}'::jsonb);end if;
 elsif p_action='begin' then
  m:=p_input->'manifest';draft:=(p_input->>'draftId')::uuid;
  if jsonb_typeof(m) is distinct from 'object' or m->>'versionId' is distinct from rid::text or m->>'workspaceId' is distinct from p_workspace::text then perform demo_desktop.fail('invalid-input');end if;
  if found then
   if r.actor_id<>p_actor or r.manifest<>m then perform demo_desktop.fail('conflict');end if;
  else
   if exists(select from demo_desktop.registration_requests where owner_id=p_owner and workspace_id=p_workspace and id=rid) then perform demo_desktop.fail('conflict');end if;
   if (select count(*) from demo_desktop.registration_request_files where owner_id=p_owner and workspace_id=p_workspace and actor_id=p_actor and state='uploading')>=20 then perform demo_desktop.fail('too-many-requests');end if;
   select grave_id into gid from demo_desktop.registration_reservations where owner_id=p_owner and workspace_id=p_workspace and id=draft and requester_id=p_actor and created_at>=clock_timestamp()-interval '24 hours';
   if not found then perform demo_desktop.fail('code-expired');end if;
   if (m->>'graveId')::bigint is distinct from gid then perform demo_desktop.fail('invalid-input');end if;
   -- The boundary must be new: not another grave's, not another pending request's (step 4-4).
   perform demo_desktop.assert_boundary_free(p_owner,p_workspace,m->'selection'->'geometry',null,rid);
   if demo_desktop.boundary_key(m->'selection'->'geometry') is not null then insert into demo_desktop.boundary_keys(owner_id,workspace_id,kind,ref,key) values(p_owner,p_workspace,'request',rid::text,demo_desktop.boundary_key(m->'selection'->'geometry'));end if;
   insert into demo_desktop.registration_request_files(owner_id,workspace_id,request_id,actor_id,grave_id,manifest) values(p_owner,p_workspace,rid,p_actor,gid,m) returning * into r;
   ext:=case when m->>'sourceFile' ~* '\.kmz$' then 'kmz' else 'kml' end;
   base:='review/'||p_workspace||'/'||rid;stage:='staging/'||p_workspace||'/'||rid;
   insert into demo_desktop.stored_objects(owner_id,workspace_id,object_key,kind,ref_kind,ref_id,grave_id) values
    (p_owner,p_workspace,base||'/original.'||ext,'earth','request',rid,gid),
    (p_owner,p_workspace,base||'/manifest.json','earth-manifest','request',rid,gid),
    (p_owner,p_workspace,stage||'/original.'||ext,'earth-staging','request',rid,gid);
   if m ? 'screenshot' then
    insert into demo_desktop.stored_objects(owner_id,workspace_id,object_key,kind,ref_kind,ref_id,grave_id) values
     (p_owner,p_workspace,base||'/earth.jpg','earth-image','request',rid,gid),
     (p_owner,p_workspace,stage||'/earth.jpg','earth-image-staging','request',rid,gid);
   end if;
  end if;
 elsif not found or r.actor_id<>p_actor then perform demo_desktop.fail('invalid-input');
 elsif p_action='publish' and r.state='uploading' then
  update demo_desktop.registration_request_files set state='ready' where owner_id=p_owner and workspace_id=p_workspace and request_id=rid returning * into r;
 end if;
 return jsonb_build_object('versionId',r.request_id,'state',r.state,'manifest',r.manifest,'keys',(
  select coalesce(jsonb_object_agg(case o.kind when 'earth' then 'original' when 'earth-manifest' then 'manifest' when 'earth-staging' then 'staging' when 'earth-image' then 'image' else 'imageStaging' end,o.object_key),'{}'::jsonb)
  from demo_desktop.stored_objects o where o.owner_id=p_owner and o.workspace_id=p_workspace and o.ref_kind='request' and o.ref_id=rid));
end $$;
revoke all on function public.demo_desktop_request_files(uuid,uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.demo_desktop_request_files(uuid,uuid,uuid,text,jsonb) to service_role;

-- Step 4-4: a master turns a pending request down. Nothing is created and the sender is not told.
-- The typed content is wiped (it is only kept while somebody may still approve it); the grave number
-- that was reserved for the location is not given out again. The location files are removed by
-- the upload function afterwards (discard), together with the boundary key.
create or replace function public.demo_desktop_registration_reject(p_workspace uuid,p_request uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;r demo_desktop.registration_requests;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'delete');
 if p_request is null then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);
 select * into r from demo_desktop.registration_requests where owner_id=o and workspace_id=p_workspace and id=p_request for update;
 if not found or r.status<>'pending' then perform demo_desktop.fail('conflict');end if;
 update demo_desktop.registration_requests set status='rejected',reviewer_id=auth.uid(),reviewed_at=clock_timestamp(),input='{}'::jsonb,requester_name='',reserved_grave_id=null where owner_id=o and workspace_id=p_workspace and id=p_request;
 delete from demo_desktop.boundary_keys where owner_id=o and workspace_id=p_workspace and kind='request' and ref=p_request::text;
 return jsonb_build_object('requestId',p_request,'rejected',true);
end $$;
revoke all on function public.demo_desktop_registration_reject(uuid,uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_registration_reject(uuid,uuid) to authenticated;

-- Step 4-3: the pending requests for the review screen (masters and submasters), oldest first.
-- The sender's input comes back as typed; the location only as a short summary (the files are
-- read separately, through the upload function).
create or replace function public.demo_desktop_registration_queue(p_workspace uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'register');
 return jsonb_build_object('items',(
  select coalesce(jsonb_agg(jsonb_build_object(
   'id',q.id,'requestedAt',q.requested_at,'requesterName',q.requester_name,'status',q.registration_status,
   'values',q.input,'hasLocation',q.has_location,'graveNumber',q.reserved_grave_id,
   'location',case when q.has_location then (select jsonb_build_object('name',f.manifest->'selection'->>'name','point',f.manifest->'selection'->'point','areaM2',f.manifest->'selection'->'areaM2','screenshot',f.manifest ? 'screenshot') from demo_desktop.registration_request_files f where f.owner_id=q.owner_id and f.workspace_id=q.workspace_id and f.request_id=q.id) end
  ) order by q.requested_at),'[]'::jsonb)
  from (select * from demo_desktop.registration_requests r where r.owner_id=o and r.workspace_id=p_workspace and r.status='pending' order by r.requested_at limit 200) q
 ),'count',(select count(*) from demo_desktop.registration_requests where owner_id=o and workspace_id=p_workspace and status='pending'));
end $$;
revoke all on function public.demo_desktop_registration_queue(uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_registration_queue(uuid) to authenticated;

-- A grave number is reserved when the sender starts looking for the location in Google Earth, so
-- the file code (데모-{번호}-{글자}) exists before the grave does. Numbers only grow: a reservation
-- that is released or expires is never given out again. An unused reservation expires after 24
-- hours; the request that uses it keeps the number until a master handles it (step 4-3/4-4).
create table if not exists demo_desktop.registration_reservations (
 owner_id uuid not null,workspace_id uuid not null,id uuid not null,
 requester_id uuid not null,grave_id bigint not null check(grave_id>0),
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,workspace_id,id),unique(owner_id,workspace_id,grave_id),
 foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id)
);
alter table demo_desktop.registration_reservations enable row level security;
revoke all on demo_desktop.registration_reservations from public,anon,authenticated,service_role;
grant select on demo_desktop.registration_reservations to demo_desktop_writer;
drop policy if exists projection_writer on demo_desktop.registration_reservations;
create policy projection_writer on demo_desktop.registration_reservations for all to demo_desktop_writer using(true) with check(true);

-- Every role that starts a new registration reserves (2026-10-24): master/submaster register
-- directly with the number, office/sales send it for review.
create or replace function demo_desktop.registration_feature(p_workspace uuid) returns text language sql stable security definer set search_path='' as $$
 select case when demo_desktop.role_allows(demo_desktop.actor_role(p_workspace),'register') then 'register' else 'register-request' end
$$;
-- The grave number reserved under this draft for the signed-in sender. p_consume: the grave is
-- created now, so the reservation is used up. A missing or expired reservation is 'code-expired'.
create or replace function demo_desktop.reserved_grave(p_owner uuid,p_workspace uuid,p_draft text,p_consume boolean) returns bigint
language plpgsql set search_path='' as $$declare gid bigint;begin
 if p_draft is null or p_draft!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then perform demo_desktop.fail('invalid-input');end if;
 select grave_id into gid from demo_desktop.registration_reservations where owner_id=p_owner and workspace_id=p_workspace and id=p_draft::uuid and requester_id=auth.uid() and created_at>=clock_timestamp()-interval '24 hours' for update;
 if not found then perform demo_desktop.fail('code-expired');end if;
 if p_consume then delete from demo_desktop.registration_reservations where owner_id=p_owner and workspace_id=p_workspace and id=p_draft::uuid;end if;
 return gid;
end $$;
create or replace function public.demo_desktop_registration_reserve(p_workspace uuid,p_draft uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;a uuid:=auth.uid();r demo_desktop.registration_reservations;gid bigint;begin
 o:=demo_desktop.assert_actor_for(p_workspace,demo_desktop.registration_feature(p_workspace));
 if p_draft is null then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);
 perform demo_desktop.lock_actor(p_workspace,o);
 delete from demo_desktop.registration_reservations where owner_id=o and workspace_id=p_workspace and created_at<clock_timestamp()-interval '24 hours';
 select * into r from demo_desktop.registration_reservations where owner_id=o and workspace_id=p_workspace and id=p_draft;
 if found then
  if r.requester_id<>a then perform demo_desktop.fail('conflict');end if;
  return jsonb_build_object('draftId',p_draft,'graveId',r.grave_id);
 end if;
 if (select count(*) from demo_desktop.registration_reservations where owner_id=o and workspace_id=p_workspace and requester_id=a)>=20 then perform demo_desktop.fail('too-many-requests');end if;
 gid:=demo_desktop.next_id(o,p_workspace,'graves');
 insert into demo_desktop.registration_reservations(owner_id,workspace_id,id,requester_id,grave_id) values(o,p_workspace,p_draft,a,gid);
 return jsonb_build_object('draftId',p_draft,'graveId',gid);
end $$;
create or replace function public.demo_desktop_registration_release(p_workspace uuid,p_draft uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid:=demo_desktop.assert_actor_for(p_workspace,demo_desktop.registration_feature(p_workspace));begin
 if p_draft is null then perform demo_desktop.fail('invalid-input');end if;
 perform demo_desktop.lock_company(o,p_workspace);
 perform demo_desktop.lock_actor(p_workspace,o);
 delete from demo_desktop.registration_reservations where owner_id=o and workspace_id=p_workspace and id=p_draft and requester_id=auth.uid();
 return jsonb_build_object('released',true);
end $$;
revoke all on function public.demo_desktop_registration_reserve(uuid,uuid),public.demo_desktop_registration_release(uuid,uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_registration_reserve(uuid,uuid),public.demo_desktop_registration_release(uuid,uuid) to authenticated;
revoke all on all functions in schema demo_desktop from public,anon,authenticated,service_role;

-- 2026-10-26 step 6-1: billing redesign (docs: claude/billing-redesign.md in the project).
-- One claim (청구서) per grave per year. It appears when the field worker's photos of an assigned
-- "진행" work are published; more claims for the same grave and year only come from "청구서 추가"
-- (later step). There are no partial payments: a claim is waiting or paid, nothing in between.
-- The first claim's amount is the grave's yearly amount (payments, kind 'annual') - one field, so
-- changing it in one place changes it everywhere. Added claims carry their own amount. A deleted
-- claim stays as a row (deleted_at) so the same photos never create it again. Permanently deleting
-- a customer removes the grave and, with it, its claims.
create table if not exists demo_desktop.claims (
 owner_id uuid not null,workspace_id uuid not null,id uuid not null,
 grave_id bigint not null,year integer not null check(year between 2000 and 9999),
 seq integer not null default 1 check(seq between 1 and 99),
 amount bigint check(amount is null or amount between 0 and 9007199254740991),
 memo text not null default '' check(char_length(memo)<=200),
 work_key text,
 created_at timestamptz not null default clock_timestamp(),created_by uuid,
 sent_at timestamptz,sent_by uuid,sent_amount bigint check(sent_amount is null or sent_amount between 0 and 9007199254740991),
 paid_at timestamptz,paid_by uuid,payer_name text check(payer_name is null or char_length(payer_name)<=50),
 thanks_at timestamptz,thanks_by uuid,
 deleted_at timestamptz,deleted_by uuid,
 version bigint not null default 1 check(version>=1),
 primary key(owner_id,workspace_id,id),
 unique(owner_id,workspace_id,grave_id,year,seq),
 check(thanks_at is null or paid_at is not null),
 foreign key(owner_id,workspace_id) references demo_desktop.companies(owner_id,workspace_id),
 foreign key(owner_id,workspace_id,grave_id) references demo_desktop.graves(owner_id,workspace_id,id) on delete cascade
);
create index if not exists claims_year on demo_desktop.claims(owner_id,workspace_id,year);
-- Step 6 2차: a customer may pay before the message goes out (after the phone call), so a claim can
-- be paid without being sent; the deposit it was matched with is kept on the claim.
do $claims$declare c text;begin
 for c in select conname from pg_constraint where conrelid='demo_desktop.claims'::regclass and contype='c'
  and pg_get_constraintdef(oid) ilike '%paid_at IS NULL%sent_at IS NOT NULL%' loop
  execute format('alter table demo_desktop.claims drop constraint %I',c);
 end loop;
end $claims$;
alter table demo_desktop.claims add column if not exists receipt_id uuid;
alter table demo_desktop.claims enable row level security;
revoke all on demo_desktop.claims from public,anon,authenticated,service_role,demo_desktop_writer;

-- The photos of an assigned work were published: make sure that grave has its claim for the work's
-- year. Never fails the publication; anything it cannot place is simply skipped.
create or replace function demo_desktop.ensure_report_claim(p_owner uuid,p_workspace uuid,p_grave bigint,p_work_key text) returns void
language plpgsql security definer set search_path='' as $$
declare y integer;begin
 select a.year into y from demo_desktop.annual_work a
  where a.owner_id=p_owner and a.workspace_id=p_workspace and 'annual:'||a.id::text=p_work_key and a.grave_id=p_grave and a.deleted_at is null;
 if y is null or not exists(select from demo_desktop.graves where owner_id=p_owner and workspace_id=p_workspace and id=p_grave) then return;end if;
 if exists(select from demo_desktop.claims where owner_id=p_owner and workspace_id=p_workspace and grave_id=p_grave and year=y) then return;end if;
 insert into demo_desktop.claims(owner_id,workspace_id,id,grave_id,year,seq,work_key)
 values(p_owner,p_workspace,gen_random_uuid(),p_grave,y,1,p_work_key) on conflict do nothing;
end $$;
revoke all on function demo_desktop.ensure_report_claim(uuid,uuid,bigint,text) from public,anon,authenticated,service_role;

-- Reports published before this step get their claims once, in the order the photos came.
insert into demo_desktop.claims(owner_id,workspace_id,id,grave_id,year,seq,work_key,created_at)
select distinct on (l.owner_id,l.workspace_id,l.grave_id,a.year)
 l.owner_id,l.workspace_id,gen_random_uuid(),l.grave_id,a.year,1,l.work_key,coalesce(r.published_at,r.created_at)
from demo_desktop.report_work_links l
join public.demo_work_reports r on r.id=l.report_id and r.state='ready'
join demo_desktop.annual_work a on a.owner_id=l.owner_id and a.workspace_id=l.workspace_id and 'annual:'||a.id::text=l.work_key and a.grave_id=l.grave_id and a.deleted_at is null
join demo_desktop.graves g on g.owner_id=l.owner_id and g.workspace_id=l.workspace_id and g.id=l.grave_id
join demo_desktop.companies co on co.owner_id=l.owner_id and co.workspace_id=l.workspace_id
where not exists(select from demo_desktop.claims c where c.owner_id=l.owner_id and c.workspace_id=l.workspace_id and c.grave_id=l.grave_id and c.year=a.year)
order by l.owner_id,l.workspace_id,l.grave_id,a.year,coalesce(r.published_at,r.created_at)
on conflict do nothing;

-- One claim as the screens show it. The status follows the dates: 문자 전 → 입금 대기 →
-- 감사 문자 전 → 끝. The amount is what was sent once the message went out; before that the first
-- claim shows the grave's yearly amount and an added claim its own.
create or replace function demo_desktop.claim_view(c demo_desktop.claims) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object(
  'id',c.id,'graveId',c.grave_id,'year',c.year,'seq',c.seq,
  'seqCount',(select count(*) from demo_desktop.claims x where x.owner_id=c.owner_id and x.workspace_id=c.workspace_id and x.grave_id=c.grave_id and x.year=c.year and x.deleted_at is null),
  'customerId',g.customer_id,'customerName',coalesce(cu.data->>'name',''),
  'address',coalesce(g.data->>'address',''),'region',demo_desktop.region(g.data->>'address'),
  'businessRegion',coalesce(g.data->>'business_region',''),
  'managed',coalesce(g.data->>'is_managed','0') in ('1','true'),
  'amount',coalesce(c.sent_amount,case when c.seq=1 then p.amount else c.amount end),
  'memo',c.memo,'createdAt',c.created_at,'sentAt',c.sent_at,'paidAt',c.paid_at,'payerName',c.payer_name,'thanksAt',c.thanks_at,
  'status',case when c.thanks_at is not null then 'done' when c.paid_at is not null then 'thanks' when c.sent_at is not null then 'wait' else 'unsent' end,
  'version',c.version)
 from demo_desktop.graves g
 left join demo_desktop.customers cu on cu.owner_id=g.owner_id and cu.workspace_id=g.workspace_id and cu.id=g.customer_id
 left join demo_desktop.payments p on p.owner_id=g.owner_id and p.workspace_id=g.workspace_id and p.grave_id=g.id and p.year=c.year and p.kind='annual'
 where g.owner_id=c.owner_id and g.workspace_id=c.workspace_id and g.id=c.grave_id
$$;
revoke all on function demo_desktop.claim_view(demo_desktop.claims) from public,anon,authenticated,service_role;

-- A claim belongs on the lists while it and its grave and customer are not deleted or hidden.
create or replace function demo_desktop.claim_listed(c demo_desktop.claims) returns boolean
language sql stable security definer set search_path='' as $$
 select c.deleted_at is null and exists(
  select from demo_desktop.graves g
  left join demo_desktop.customers cu on cu.owner_id=g.owner_id and cu.workspace_id=g.workspace_id and cu.id=g.customer_id
  where g.owner_id=c.owner_id and g.workspace_id=c.workspace_id and g.id=c.grave_id
   and nullif(g.data->>'deleted_at','') is null and nullif(cu.data->>'deleted_at','') is null)
$$;
revoke all on function demo_desktop.claim_listed(demo_desktop.claims) from public,anon,authenticated,service_role;

-- The 청구·입금 screen (owner, master, submaster, office): every claim of one year.
create or replace function public.demo_desktop_billing_list(p_workspace uuid,p_year integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;this_year integer:=extract(year from clock_timestamp() at time zone 'Asia/Seoul')::integer;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'billing');
 if p_year is null or p_year not between 2000 and 9999 then perform demo_desktop.fail('invalid-input');end if;
 return jsonb_build_object('year',p_year,
  'years',(select coalesce(jsonb_agg(y order by y desc),'[]') from (
   select distinct year y from demo_desktop.claims where owner_id=o and workspace_id=p_workspace and deleted_at is null
   union select this_year) years),
  'claims',(select coalesce(jsonb_agg(demo_desktop.claim_view(c) order by c.created_at,c.seq,c.id),'[]')
   from demo_desktop.claims c where c.owner_id=o and c.workspace_id=p_workspace and c.year=p_year and demo_desktop.claim_listed(c)));
end $$;
revoke all on function public.demo_desktop_billing_list(uuid,integer) from public,anon,service_role;
grant execute on function public.demo_desktop_billing_list(uuid,integer) to authenticated;

-- One claim with the work reports of that grave and year (newest first). The photos themselves are
-- fetched like any report's photos.
create or replace function public.demo_desktop_billing_claim(p_workspace uuid,p_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;c demo_desktop.claims;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'billing');
 select * into c from demo_desktop.claims where owner_id=o and workspace_id=p_workspace and id=p_id;
 if not found or not demo_desktop.claim_listed(c) then perform demo_desktop.fail('conflict');end if;
 return demo_desktop.claim_view(c)||jsonb_build_object('reports',(
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'publishedAt',coalesce(r.published_at,r.created_at),
   'reporterName',r.reporter_name,'location',r.location,'photoCount',jsonb_array_length(r.photos)) order by coalesce(r.published_at,r.created_at) desc,r.id),'[]')
  from demo_desktop.report_work_links l
  join public.demo_work_reports r on r.id=l.report_id and r.state='ready' and r.desktop_archived_at is null
  join demo_desktop.annual_work a on a.owner_id=l.owner_id and a.workspace_id=l.workspace_id and 'annual:'||a.id::text=l.work_key
  where l.owner_id=o and l.workspace_id=p_workspace and l.grave_id=c.grave_id and a.year=c.year));
end $$;
revoke all on function public.demo_desktop_billing_claim(uuid,uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_billing_claim(uuid,uuid) to authenticated;

-- 확인 대기 입금 (step 6-4 read side). A depositor name that differs from the customer's name is
-- remembered for that customer once a person confirms such a deposit. It never shows on customer
-- screens and never confirms a deposit by itself: it only puts the customer's claims on the list
-- of candidates the next time. Permanently deleting the customer removes it.
create table if not exists demo_desktop.payer_names (
 owner_id uuid not null,workspace_id uuid not null,customer_id bigint not null,
 name text not null check(char_length(name) between 1 and 50),
 created_at timestamptz not null default clock_timestamp(),created_by uuid,
 primary key(owner_id,workspace_id,customer_id,name),
 foreign key(owner_id,workspace_id,customer_id) references demo_desktop.customers(owner_id,workspace_id,id) on delete cascade
);
create index if not exists payer_names_name on demo_desktop.payer_names(owner_id,workspace_id,name);
alter table demo_desktop.payer_names enable row level security;
revoke all on demo_desktop.payer_names from public,anon,authenticated,service_role,demo_desktop_writer;

-- A held bank deposit (the Galaxy could not place it) with the claims a person may pick from.
-- Only claims waiting for their money are candidates. Each claim is in its strongest group:
-- both (name and amount match, but more than one claim does), payer (a remembered other
-- depositor name), name (same name, other amount), amount (same amount, other name).
create or replace function demo_desktop.pending_view(o uuid,w uuid,r public.demo_bank_receipts) returns jsonb
language sql stable security definer set search_path='' as $$
 with waiting as (
  select demo_desktop.claim_view(c) v,btrim(coalesce(cu.data->>'name','')) customer_name,cu.id customer_id
  from demo_desktop.claims c
  join demo_desktop.graves g on g.owner_id=c.owner_id and g.workspace_id=c.workspace_id and g.id=c.grave_id
  left join demo_desktop.customers cu on cu.owner_id=g.owner_id and cu.workspace_id=g.workspace_id and cu.id=g.customer_id
  where c.owner_id=o and c.workspace_id=w and c.sent_at is not null and c.paid_at is null and demo_desktop.claim_listed(c)
 ),grouped as (
  select v,case
   when customer_name=btrim(r.payer) and (v->>'amount')::bigint is not distinct from r.amount then 'both'
   when exists(select from demo_desktop.payer_names p where p.owner_id=o and p.workspace_id=w and p.customer_id=waiting.customer_id and p.name=btrim(r.payer)) then 'payer'
   when customer_name=btrim(r.payer) then 'name'
   when (v->>'amount')::bigint is not distinct from r.amount then 'amount' end grp
  from waiting
 )
 select jsonb_build_object('id',r.id,'payer',r.payer,'amount',r.amount,'at',coalesce(r.bank_at,r.received_at),
  'groups',jsonb_build_object(
   'both',coalesce(jsonb_agg(v order by v->>'createdAt') filter(where grp='both'),'[]'),
   'payer',coalesce(jsonb_agg(v order by v->>'createdAt') filter(where grp='payer'),'[]'),
   'name',coalesce(jsonb_agg(v order by v->>'createdAt') filter(where grp='name'),'[]'),
   'amount',coalesce(jsonb_agg(v order by v->>'createdAt') filter(where grp='amount'),'[]')))
 from grouped
$$;
revoke all on function demo_desktop.pending_view(uuid,uuid,public.demo_bank_receipts) from public,anon,authenticated,service_role;

create or replace function public.demo_desktop_billing_pending(p_workspace uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'billing');
 return jsonb_build_object('deposits',(
  select coalesce(jsonb_agg(demo_desktop.pending_view(o,p_workspace,r) order by coalesce(r.bank_at,r.received_at) desc,r.id),'[]')
  from (select * from public.demo_bank_receipts where owner_id=o and workspace_id=p_workspace and status='held'
   order by coalesce(bank_at,received_at) desc,id limit 200) r));
end $$;
revoke all on function public.demo_desktop_billing_pending(uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_billing_pending(uuid) to authenticated;

-- 확인 대기 입금 "직접 찾기": this year's 진행 works (graves), each with its claims if any, so a
-- person can attach a deposit to someone the matching did not suggest. The saved order sheets of the
-- year come along (named like the 작업 확인 tabs) so the search can be narrowed to one sheet.
-- Loaded once per popup.
create or replace function public.demo_desktop_billing_works(p_workspace uuid,p_year integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'billing');
 if p_year is null or p_year not between 2000 and 9999 then perform demo_desktop.fail('invalid-input');end if;
 return jsonb_build_object('year',p_year,
  'sheets',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,
    'title',(select string_agg(x,'/' order by n) from jsonb_array_elements_text(coalesce(r.data->'regions','[]')) with ordinality t(x,n)),
    'workKeys',coalesce(r.data->'workKeys','[]')) order by r.id),'[]')
   from demo_desktop.work_routes r where r.owner_id=o and r.workspace_id=p_workspace and r.year=p_year),
  'works',(
  select coalesce(jsonb_agg(w.item order by w.item->>'customerName',(w.item->>'graveId')::bigint),'[]') from (
   select jsonb_build_object('workKey','annual:'||a.id::text,'graveId',g.id,'customerId',cu.id,
    'customerName',coalesce(cu.data->>'name',''),'address',coalesce(g.data->>'address',''),
    'region',demo_desktop.region(g.data->>'address'),'amount',p.amount,
    'claims',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'seq',c.seq,
      'amount',coalesce(c.sent_amount,case when c.seq=1 then p.amount else c.amount end),'sentAt',c.sent_at,
      'status',case when c.thanks_at is not null then 'done' when c.paid_at is not null then 'thanks' when c.sent_at is not null then 'wait' else 'unsent' end)
      order by c.seq),'[]')
     from demo_desktop.claims c where c.owner_id=o and c.workspace_id=p_workspace and c.grave_id=g.id and c.year=a.year and c.deleted_at is null)) item
   from demo_desktop.annual_work a
   join demo_desktop.graves g on g.owner_id=a.owner_id and g.workspace_id=a.workspace_id and g.id=a.grave_id
   left join demo_desktop.customers cu on cu.owner_id=g.owner_id and cu.workspace_id=g.workspace_id and cu.id=g.customer_id
   left join demo_desktop.payments p on p.owner_id=g.owner_id and p.workspace_id=g.workspace_id and p.grave_id=g.id and p.year=a.year and p.kind='annual'
   where a.owner_id=o and a.workspace_id=p_workspace and a.year=p_year and a.status='proceed' and a.deleted_at is null
    and nullif(g.data->>'deleted_at','') is null and nullif(cu.data->>'deleted_at','') is null
   limit 3000) w));
end $$;
revoke all on function public.demo_desktop_billing_works(uuid,integer) from public,anon,service_role;
grant execute on function public.demo_desktop_billing_works(uuid,integer) to authenticated;

-- Step 6 2차: what a person does on the 청구·입금 screen. Every change locks the claims it touches
-- and checks their state again, so two people pressing at once cannot both win.
create or replace function demo_desktop.claim_for_update(o uuid,w uuid,p_id uuid) returns demo_desktop.claims
language plpgsql security definer set search_path='' as $$
declare c demo_desktop.claims;begin
 select * into c from demo_desktop.claims where owner_id=o and workspace_id=w and id=p_id for update;
 if not found or not demo_desktop.claim_listed(c) then perform demo_desktop.fail('conflict');end if;
 return c;
end $$;
revoke all on function demo_desktop.claim_for_update(uuid,uuid,uuid) from public,anon,authenticated,service_role;

-- A depositor name that differs from the customer's is remembered for that customer.
create or replace function demo_desktop.remember_payer(o uuid,w uuid,p_grave bigint,p_name text,p_actor uuid) returns void
language plpgsql security definer set search_path='' as $$
declare cid bigint;cname text;begin
 select g.customer_id,btrim(coalesce(cu.data->>'name','')) into cid,cname from demo_desktop.graves g
  left join demo_desktop.customers cu on cu.owner_id=g.owner_id and cu.workspace_id=g.workspace_id and cu.id=g.customer_id
  where g.owner_id=o and g.workspace_id=w and g.id=p_grave;
 if cid is null or btrim(coalesce(p_name,''))='' or btrim(p_name)=cname then return;end if;
 insert into demo_desktop.payer_names(owner_id,workspace_id,customer_id,name,created_by)
 values(o,w,cid,left(btrim(p_name),50),p_actor) on conflict do nothing;
end $$;
revoke all on function demo_desktop.remember_payer(uuid,uuid,bigint,text,uuid) from public,anon,authenticated,service_role;

-- 확인 대기 입금: confirm a held deposit for one or more claims (a deposit may pay several graves
-- at once), or set it aside as not the company's. A 진행 grave without a claim gets its first claim.
create or replace function public.demo_desktop_billing_resolve(p_workspace uuid,p_input jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;actor uuid:=auth.uid();r public.demo_bank_receipts;target jsonb;c demo_desktop.claims;
 a demo_desktop.annual_work;ids uuid[]:='{}';first uuid;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'billing');
 if jsonb_typeof(p_input) is distinct from 'object' or coalesce(p_input->>'action','') not in ('confirm','ignore')
  or not coalesce(p_input->>'receiptId','') ~ '^[0-9a-fA-F-]{36}$' then perform demo_desktop.fail('invalid-input');end if;
 select * into r from public.demo_bank_receipts where owner_id=o and workspace_id=p_workspace and id=(p_input->>'receiptId')::uuid for update;
 if not found or r.status<>'held' then perform demo_desktop.fail('conflict');end if;
 if p_input->>'action'='ignore' then
  update public.demo_bank_receipts set status='ignored',reason='desktop-ignored',resolved_by=actor,updated_at=clock_timestamp() where owner_id=o and workspace_id=p_workspace and id=r.id;
  return jsonb_build_object('receiptId',r.id,'ignored',true);
 end if;
 if jsonb_typeof(p_input->'targets') is distinct from 'array' or jsonb_array_length(p_input->'targets') not between 1 and 20 then perform demo_desktop.fail('invalid-input');end if;
 for target in select value from jsonb_array_elements(p_input->'targets') loop
  if jsonb_typeof(target) is distinct from 'object' then perform demo_desktop.fail('invalid-input');end if;
  if target ? 'claimId' then
   if not coalesce(target->>'claimId','') ~ '^[0-9a-fA-F-]{36}$' then perform demo_desktop.fail('invalid-input');end if;
   c:=demo_desktop.claim_for_update(o,p_workspace,(target->>'claimId')::uuid);
  elsif target ? 'workKey' then
   select * into a from demo_desktop.annual_work where owner_id=o and workspace_id=p_workspace and 'annual:'||id::text=target->>'workKey'
    and status='proceed' and deleted_at is null and grave_id is not null for update;
   if not found then perform demo_desktop.fail('conflict');end if;
   if exists(select from demo_desktop.claims where owner_id=o and workspace_id=p_workspace and grave_id=a.grave_id and year=a.year) then perform demo_desktop.fail('conflict');end if;
   insert into demo_desktop.claims(owner_id,workspace_id,id,grave_id,year,seq,work_key,created_by)
   values(o,p_workspace,gen_random_uuid(),a.grave_id,a.year,1,target->>'workKey',actor) returning * into c;
  else perform demo_desktop.fail('invalid-input');end if;
  if c.paid_at is not null or c.id=any(ids) then perform demo_desktop.fail('conflict');end if;
  update demo_desktop.claims set paid_at=coalesce(r.bank_at,r.received_at),paid_by=actor,payer_name=left(r.payer,50),receipt_id=r.id,version=version+1
   where owner_id=o and workspace_id=p_workspace and id=c.id;
  if coalesce((p_input->>'remember')::boolean,false) then perform demo_desktop.remember_payer(o,p_workspace,c.grave_id,r.payer,actor);end if;
  ids:=ids||c.id;first:=coalesce(first,c.id);
 end loop;
 update public.demo_bank_receipts set status='matched',reason='desktop-confirmed',claim_id=first,resolved_by=actor,updated_at=clock_timestamp()
  where owner_id=o and workspace_id=p_workspace and id=r.id;
 return jsonb_build_object('receiptId',r.id,'claimIds',to_jsonb(ids));
end $$;
revoke all on function public.demo_desktop_billing_resolve(uuid,jsonb) from public,anon,service_role;
grant execute on function public.demo_desktop_billing_resolve(uuid,jsonb) to authenticated;

-- 청구서 상세: 입금 직접 확인 (billing), 입금 취소 and 청구서 삭제 (delete: owner and master).
-- One grave has one claim a year (user decision 2026-10-26: no extra claims for now).
--
-- owner and master). A cancelled payment that came from a bank deposit sends the deposit back to
-- 확인 대기 when no other claim still uses it.
create or replace function public.demo_desktop_billing_claim_action(p_workspace uuid,p_input jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;actor uuid:=auth.uid();act text:=p_input->>'action';c demo_desktop.claims;d date;begin
 if jsonb_typeof(p_input) is distinct from 'object' or coalesce(act,'') not in ('pay','unpay','delete')
  or not coalesce(p_input->>'claimId','') ~ '^[0-9a-fA-F-]{36}$' then perform demo_desktop.fail('invalid-input');end if;
 o:=demo_desktop.assert_actor_for(p_workspace,case when act in ('unpay','delete') then 'delete' else 'billing' end);
 c:=demo_desktop.claim_for_update(o,p_workspace,(p_input->>'claimId')::uuid);
 if act='pay' then
  if c.paid_at is not null then perform demo_desktop.fail('conflict');end if;
  begin d:=(p_input->>'paidOn')::date;exception when others then perform demo_desktop.fail('invalid-input');end;
  if d is null or d>(clock_timestamp() at time zone 'Asia/Seoul')::date or btrim(coalesce(p_input->>'payerName',''))=''
   or char_length(p_input->>'payerName')>50 then perform demo_desktop.fail('invalid-input');end if;
  update demo_desktop.claims set paid_at=(d::timestamp+interval '12 hours') at time zone 'Asia/Seoul',paid_by=actor,
   payer_name=btrim(p_input->>'payerName'),receipt_id=null,version=version+1 where owner_id=o and workspace_id=p_workspace and id=c.id;
  perform demo_desktop.remember_payer(o,p_workspace,c.grave_id,p_input->>'payerName',actor);
  return jsonb_build_object('claimId',c.id,'paid',true);
 elsif act='unpay' then
  if c.paid_at is null or c.thanks_at is not null then perform demo_desktop.fail('conflict');end if;
  update demo_desktop.claims set paid_at=null,paid_by=null,payer_name=null,receipt_id=null,version=version+1 where owner_id=o and workspace_id=p_workspace and id=c.id;
  if c.receipt_id is not null and not exists(select from demo_desktop.claims where owner_id=o and workspace_id=p_workspace and receipt_id=c.receipt_id) then
   update public.demo_bank_receipts set status='held',reason='desktop-unpaid',claim_id=null,resolved_by=actor,updated_at=clock_timestamp()
    where owner_id=o and workspace_id=p_workspace and id=c.receipt_id;
  end if;
  return jsonb_build_object('claimId',c.id,'unpaid',true);
 else
  if c.paid_at is not null then perform demo_desktop.fail('conflict');end if;
  update demo_desktop.claims set deleted_at=clock_timestamp(),deleted_by=actor,version=version+1 where owner_id=o and workspace_id=p_workspace and id=c.id;
  return jsonb_build_object('claimId',c.id,'deleted',true);
 end if;
end $$;
revoke all on function public.demo_desktop_billing_claim_action(uuid,jsonb) from public,anon,service_role;
grant execute on function public.demo_desktop_billing_claim_action(uuid,jsonb) to authenticated;

-- Step 6-3 (부마스터 휴대폰): the customer list for 고객 찾기, and 청구 on the phone.
-- 작업 확인 lists the claims whose 청구 문자 is still to go; tapping one opens the 청구 문자 screen.
-- 청구 has 입금 대기 and 최종 문자. One grave has one claim a year (2026-10-26).

-- While one phone sends a claim's 청구 문자 the others see "보내는 중" for ten minutes.
alter table demo_desktop.claims add column if not exists sending_at timestamptz;
alter table demo_desktop.claims add column if not exists sending_by uuid;

-- 고객 찾기 on a 부마스터 phone: the company's current customers, graves and this year's work, the
-- same as the PC reads (role 'read'), with the map pins workers get. Unchanged data comes back as
-- one short answer.
create or replace function public.demo_desktop_phone_data_if_changed(p_workspace uuid,p_revision text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare o uuid;c jsonb;pins jsonb;data jsonb;revision text;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'read');
 c:=demo_desktop.allocation_catalog(o,p_workspace);
 if c is null then perform demo_desktop.fail('conflict');end if;
 select payload into pins from public.demo_map_snapshots where owner_id=o and workspace_id=p_workspace;
 data:=jsonb_build_object(
  'catalog',c||jsonb_build_object('format','demo-catalog','version',1,'workspaceId',p_workspace),
  'mapSnapshot',jsonb_build_object('workspaceId',p_workspace,'locations',(
   select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(coalesce(pins->'locations','[]')) r
   where (r->'location'->>'source'<>'google' or (r->'location'->>'expiresAt')::numeric>extract(epoch from now())*1000)
    and public.demo_location_grave(o,p_workspace,(r->>'id')::bigint) is not null)));
 revision:=md5(data::text);
 if revision=p_revision then return jsonb_build_object('revision',revision,'unchanged',true);end if;
 return data||jsonb_build_object('revision',revision,'unchanged',false);
end $$;
revoke all on function public.demo_desktop_phone_data_if_changed(uuid,text) from public,anon,service_role;
grant execute on function public.demo_desktop_phone_data_if_changed(uuid,text) to authenticated;

-- 고객 찾기 → 지도에서 보기: the location screenshot saved with the grave's Google Earth version (the
-- same one a field worker sees on an assigned place). The earth-assets function signs the image.
create or replace function public.demo_desktop_grave_screenshot(p_workspace uuid,p_grave bigint) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare o uuid;c jsonb;g jsonb;begin
 o:=demo_desktop.assert_actor_for(p_workspace,'read');
 c:=demo_desktop.allocation_catalog(o,p_workspace);
 select x into g from (
  select x from jsonb_array_elements(coalesce(c->'customers','[]')) person cross join lateral jsonb_array_elements(coalesce(person->'graves','[]')) x
   where nullif(person->>'deleted_at','') is null and coalesce(person->>'registration_status','')<>'declined'
  union all select x from jsonb_array_elements(coalesce(c->'unassignedGraves','[]')) x
 ) graves where x->>'id'=p_grave::text and nullif(x->>'deleted_at','') is null limit 1;
 if g is null then perform demo_desktop.fail('conflict');end if;
 return jsonb_build_object('manifest',demo_desktop.grave_screenshot(o,p_workspace,g));
end $$;
revoke all on function public.demo_desktop_grave_screenshot(uuid,bigint) from public,anon,service_role;
grant execute on function public.demo_desktop_grave_screenshot(uuid,bigint) to authenticated;

-- The phone's three lists in one answer: every claim not finished yet, with the customer's phone
-- number, the work reports of that grave and year, and who is sending it right now.
create or replace function public.demo_desktop_billing_phone(p_workspace uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;actor uuid:=auth.uid();begin
 o:=demo_desktop.assert_actor_for(p_workspace,'billing');
 return jsonb_build_object('claims',(
  select coalesce(jsonb_agg(x.v order by x.at desc,x.v->>'id'),'[]') from (
   select demo_desktop.claim_view(c)||jsonb_build_object(
     'phone',coalesce(cu.data->>'phone',''),
     'sending',case when c.sent_at is null and c.sending_at>clock_timestamp()-interval '10 minutes' then
      jsonb_build_object('mine',c.sending_by=actor,'at',c.sending_at,
       'name',coalesce((select m.display_name from public.demo_members m where m.user_id=c.sending_by),'사장님')) end,
     'reports',coalesce(rep.list,'[]'::jsonb)) v,
    coalesce(rep.latest,c.created_at) at
   from demo_desktop.claims c
   join demo_desktop.graves g on g.owner_id=c.owner_id and g.workspace_id=c.workspace_id and g.id=c.grave_id
   left join demo_desktop.customers cu on cu.owner_id=g.owner_id and cu.workspace_id=g.workspace_id and cu.id=g.customer_id
   left join lateral (
    select jsonb_agg(jsonb_build_object('id',r.id,'publishedAt',coalesce(r.published_at,r.created_at),
      'reporterName',r.reporter_name,'photoCount',jsonb_array_length(r.photos)) order by coalesce(r.published_at,r.created_at) desc,r.id) list,
     max(coalesce(r.published_at,r.created_at)) latest
    from demo_desktop.report_work_links l
    join public.demo_work_reports r on r.id=l.report_id and r.state='ready' and r.desktop_archived_at is null
    join demo_desktop.annual_work a on a.owner_id=l.owner_id and a.workspace_id=l.workspace_id and 'annual:'||a.id::text=l.work_key
    where l.owner_id=c.owner_id and l.workspace_id=c.workspace_id and l.grave_id=c.grave_id and a.year=c.year) rep on true
   where c.owner_id=o and c.workspace_id=p_workspace and c.thanks_at is null and demo_desktop.claim_listed(c)
  ) x));
end $$;
revoke all on function public.demo_desktop_billing_phone(uuid) from public,anon,service_role;
grant execute on function public.demo_desktop_billing_phone(uuid) to authenticated;

-- What the phone does to a claim:
-- sending  holds the claim for ten minutes so a second phone does not send it too
-- release  lets it go again (the message did not go out)
-- sent     the message went out: the amount sent is fixed, and a changed amount becomes the
--          grave's amount for that year too
-- thanks   the 최종 문자 went out (only after the payment)
create or replace function public.demo_desktop_billing_phone_action(p_workspace uuid,p_input jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o uuid;actor uuid:=auth.uid();act text:=p_input->>'action';c demo_desktop.claims;sent_value bigint;current_amount bigint;cid bigint;begin
 if jsonb_typeof(p_input) is distinct from 'object' or coalesce(act,'') not in ('sending','release','sent','thanks')
  or p_input-array['action','claimId','amount']<>'{}'
  or not coalesce(p_input->>'claimId','') ~ '^[0-9a-fA-F-]{36}$' then perform demo_desktop.fail('invalid-input');end if;
 o:=demo_desktop.assert_actor_for(p_workspace,'billing');
 c:=demo_desktop.claim_for_update(o,p_workspace,(p_input->>'claimId')::uuid);
 if act='sending' then
  if c.sent_at is not null or c.paid_at is not null then perform demo_desktop.fail('conflict');end if;
  if c.sending_at>clock_timestamp()-interval '10 minutes' and c.sending_by is distinct from actor then perform demo_desktop.fail('conflict');end if;
  update demo_desktop.claims set sending_at=clock_timestamp(),sending_by=actor where owner_id=o and workspace_id=p_workspace and id=c.id;
  return jsonb_build_object('claimId',c.id,'sending',true);
 elsif act='release' then
  if c.sending_by=actor then
   update demo_desktop.claims set sending_at=null,sending_by=null where owner_id=o and workspace_id=p_workspace and id=c.id;
  end if;
  return jsonb_build_object('claimId',c.id,'released',true);
 elsif act='sent' then
  -- A phone that learns the result late may report it twice; the first report stands.
  if c.sent_at is not null then return jsonb_build_object('claimId',c.id,'sent',true);end if;
  begin sent_value:=(p_input->>'amount')::bigint;exception when others then perform demo_desktop.fail('invalid-input');end;
  if sent_value is null or sent_value<=0 or sent_value>9007199254740991 then perform demo_desktop.fail('invalid-input');end if;
  current_amount:=(demo_desktop.claim_view(c)->>'amount')::bigint;
  if current_amount is distinct from sent_value then
   perform demo_desktop.write_payment(o,p_workspace,c.grave_id,c.year,'annual',sent_value,'phone_claim');
   select customer_id into cid from demo_desktop.graves where owner_id=o and workspace_id=p_workspace and id=c.grave_id;
   perform demo_desktop.bump(o,p_workspace,cid,c.grave_id);
  end if;
  update demo_desktop.claims set sent_at=clock_timestamp(),sent_by=actor,sent_amount=sent_value,sending_at=null,sending_by=null,version=version+1
   where owner_id=o and workspace_id=p_workspace and id=c.id;
  return jsonb_build_object('claimId',c.id,'sent',true);
 else
  if c.thanks_at is not null then return jsonb_build_object('claimId',c.id,'thanks',true);end if;
  if c.paid_at is null then perform demo_desktop.fail('conflict');end if;
  update demo_desktop.claims set thanks_at=clock_timestamp(),thanks_by=actor,version=version+1
   where owner_id=o and workspace_id=p_workspace and id=c.id;
  return jsonb_build_object('claimId',c.id,'thanks',true);
 end if;
end $$;
revoke all on function public.demo_desktop_billing_phone_action(uuid,jsonb) from public,anon,service_role;
grant execute on function public.demo_desktop_billing_phone_action(uuid,jsonb) to authenticated;

-- Phones learn about claim changes (a new claim, a payment, a message sent, "보내는 중") from the
-- company's billing signal, the same way they learn about new reports. No polling.
do $$ declare op text;refs text;begin
 if to_regprocedure('public.demo_signal_changed()') is null then return;end if;
 foreach op in array array['insert','update','delete'] loop
  refs:=case op when 'insert' then 'new table as new_rows' when 'delete' then 'old table as old_rows'
   else 'old table as old_rows new table as new_rows' end;
  execute format('drop trigger if exists %I on demo_desktop.claims','billing_signal_'||op);
  execute format('create trigger %I after %s on demo_desktop.claims referencing %s for each statement execute function public.demo_signal_changed(%L)',
   'billing_signal_'||op,op,refs,'billing');
 end loop;
end $$;

-- Step 6-4 (2026-10-26): the Galaxy's bank deposits pay the new claims (one claim per grave a year).
-- A deposit pays a claim by itself only when exactly one claim waiting for its money (청구 문자 sent
-- no later than the deposit, not paid yet) has the depositor's name as its customer's name and the
-- deposit's amount. Every other deposit waits in 확인 대기 on the PC. The matching rule runs in the
-- bank-deposits function (src/shared/bank-deposits.cjs); here are the claims it reads and the write.
-- These replace the event-ledger versions of public.demo_bank_context and public.demo_bank_commit.

create or replace function public.demo_bank_context(p_owner uuid,p_workspace uuid,p_id uuid,p_fingerprint text) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('head',0,'privacyEnabled',demo_desktop.privacy_enabled(p_owner,p_workspace),
  'receipt',(select to_jsonb(r) from public.demo_bank_receipts r where r.owner_id=p_owner and r.workspace_id=p_workspace and r.id=p_id),
  'duplicate',exists(select from public.demo_bank_receipts r where r.owner_id=p_owner and r.workspace_id=p_workspace and r.id<>p_id and r.fingerprint=p_fingerprint),
  'claims',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'customerName',coalesce(cu.data->>'name',''),
     'amount',(demo_desktop.claim_view(c)->>'amount')::bigint,'sentAt',c.sent_at) order by c.sent_at,c.id),'[]')
   from demo_desktop.claims c
   join demo_desktop.graves g on g.owner_id=c.owner_id and g.workspace_id=c.workspace_id and g.id=c.grave_id
   left join demo_desktop.customers cu on cu.owner_id=g.owner_id and cu.workspace_id=g.workspace_id and cu.id=g.customer_id
   where c.owner_id=p_owner and c.workspace_id=p_workspace and c.sent_at is not null and c.paid_at is null
    and demo_desktop.claim_listed(c)))
 where exists(select from demo_desktop.companies where owner_id=p_owner and workspace_id=p_workspace and active)
$$;

-- p_head is no longer used: the claim row is locked and checked again instead.
create or replace function public.demo_bank_commit(p_owner uuid,p_workspace uuid,p_actor uuid,p_hash text,p_receipt jsonb,p_head bigint,p_status text,p_claim uuid,p_reason text,p_manual boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r public.demo_bank_receipts;v_id uuid:=(p_receipt->>'id')::uuid;c demo_desktop.claims;at_paid timestamptz;begin
 perform 1 from demo_desktop.companies where owner_id=p_owner and workspace_id=p_workspace and active for share;
 if not found then raise exception 'Company missing';end if;
 if not public.demo_bank_actor(p_owner,p_workspace,p_actor) then raise exception 'Access denied';end if;
 if p_hash is not null and not exists(select from public.demo_bank_devices where owner_id=p_owner and workspace_id=p_workspace and actor_id=p_actor and active and token_hash=p_hash) then raise exception 'Device revoked';end if;
 -- A held deposit is confirmed on the PC (확인 대기, public.demo_desktop_billing_resolve).
 if p_manual then raise exception 'Use the billing screen';end if;
 select * into r from public.demo_bank_receipts where owner_id=p_owner and workspace_id=p_workspace and id=v_id for update;
 if found then return to_jsonb(r);end if;
 if p_status not in ('held','matched') then raise exception 'Invalid status';end if;
 if p_status='matched' and exists(select from public.demo_bank_receipts where owner_id=p_owner and workspace_id=p_workspace and id<>v_id and fingerprint=p_receipt->>'fingerprint') then
  p_status:='held';p_claim:=null;p_reason:='같은 시각·이름·금액의 입금 확인 필요';
 end if;
 at_paid:=coalesce((p_receipt->>'bankAt')::timestamptz,(p_receipt->>'receivedAt')::timestamptz);
 if p_status='matched' then
  select * into c from demo_desktop.claims where owner_id=p_owner and workspace_id=p_workspace and id=p_claim for update;
  -- The claim may have changed since the matching read it: then the deposit waits for a person.
  if not found or not demo_desktop.claim_listed(c) or c.paid_at is not null or c.sent_at is null or c.sent_at>at_paid
   or (demo_desktop.claim_view(c)->>'amount')::bigint is distinct from (p_receipt->>'amount')::bigint then
   p_status:='held';p_claim:=null;p_reason:='청구서가 바뀌어 확인 필요';
  else
   update demo_desktop.claims set paid_at=at_paid,paid_by=null,payer_name=left(coalesce(p_receipt->>'payer',''),50),receipt_id=v_id,version=version+1
    where owner_id=p_owner and workspace_id=p_workspace and id=c.id;
  end if;
 end if;
 insert into public.demo_bank_receipts(owner_id,workspace_id,id,amount,payer,bank_at,received_at,excerpt,fingerprint,status,reason,claim_id,payment_id,resolved_by)
 values(p_owner,p_workspace,v_id,(p_receipt->>'amount')::bigint,coalesce(p_receipt->>'payer',''),(p_receipt->>'bankAt')::timestamptz,(p_receipt->>'receivedAt')::timestamptz,p_receipt->>'text',p_receipt->>'fingerprint',p_status,coalesce(p_reason,''),p_claim,null,null)
 returning * into r;
 return to_jsonb(r);
end $$;
revoke all on function public.demo_bank_context(uuid,uuid,uuid,text),public.demo_bank_commit(uuid,uuid,uuid,text,jsonb,bigint,text,uuid,text,boolean) from public,anon,authenticated;
